// Dữ liệu Ân Đức Tam Bảo
const ANDUC_DATA = {"phat": {"title": "Ân Đức Phật", "pali": "Buddhaguṇa · 9 ân đức", "kinh": "Itipi so bhagavā <b>arahaṁ sammāsambuddho vijjācaraṇasampanno sugato lokavidū anuttaro purisadammasārathi satthā devamanussānaṁ buddho bhagavā</b>ti.", "items": [{"n": 1, "pali": "Arahaṁ", "paliUp": "ARAHAṂ", "vi": "Ứng Cúng", "short": "<p>Ngài đã đoạn tận trọn vẹn mọi phiền não cùng với mọi tập khí, không còn chỗ kín nào để làm điều ác, đã bẻ gãy bánh xe luân hồi — nên xứng đáng được chư thiên và nhân loại lễ bái cúng dường.</p>", "detail": "<ol type=\"1\">\n<li>Nghĩa là Đức Phật, bằng đạo siêu thế (lokuttarā-magga) Ngài đã đọan\ntận tất cả phiền não (kilesās), số lượng lên đến một ngàn năm trăm,\nkhông còn dư sót. Phiền não được ví như những kẻ thù phá hoại hạnh phúc\nvà lợi ích của người. Các phiền não có mặt trong dòng danh sắc của Đức\nPhật đương lai; chúng được gọi là kẻ thù (ari).</li>\n</ol>\n<p>Sau khi Đức Phật quán về pháp Duyên khởi, được gọi là Mahāvajira\nVipassanā, Ngài đã đạt được sự Giác ngộ tối thượng trên bồ đoàn chiến\nthắng. Bốn đạo Siêu thế giúp ngài đọan diệt tất cả những phiền não, từ\nnhóm này đến nhóm khác. Bởi vậy pháp Siêu thế, tức là Bốn Thánh đạo, là\nân đức được gọi là Arahaṁ trong khi dòng Danh Sắc trong năm uẩn của Đức\nPhật là người sở hữu ân đức ấy.</p>\n<ol start=\"2\" type=\"1\">\n<li>Có nguồn gốc của arahaṁ từ gốc araha của nó, ý nghĩa là ’ người đã\nxa lìa các phiền não.’ Như đã giải thích ở phần (a), Đức Phật đã đọan\ndiệt tất cả phiền não cùng với khuynh hướng vi tế đối với hình thức huân\ntập nào đó mà không để lại dấu vết; ngay cả ấn tượng lờ mờ về chúng cũng\nkhông còn. Các phiền não và khuynh hướng không có khả năng sanh khởi lại\ntrong tâm Đức Phật. Theo ý nghĩa này thì Đức Phật đã xa lìa tất cả phiền\nnão và các khuynh hướng. Ngài đã xa lìa chúng một cách rốt ráo. Sự đọan\ndiệt tất cả phiền não cùng với các khuynh hướng một cách tuyệt đối này\nlà ân đức Arahaṁ và dòng Danh Sắc trong ngũ uẩn của Đức Phật chính là\nngười sở hữu ân đức ấy. Ân đức này xuất phát từ bốn Thánh đạo.</li>\n</ol>\n<p>(Những ân đức kể trên được giải thích trong phần (a) và (b) thì những\nvị A-la-hán khác không có. Lý do là tất cả các vị A-la-hán đều đọan diệt\nhết thảy một ngàn năm trăm kilesa, nhưng không giống như Đức Phật, những\nấn tượng lờ mờ hay những dấu vết về khuynh hướng của các vị ấy đối với\nmột số thói quen vẫn còn tồn tại với họ.</p>\n<p>Ấn tượng lờ mờ là khuynh hướng vi tế vẫn còn trong dòng tâm của vị\nA-la-hán bình thường, có thể vô ý làm cho một hành động nào đó sanh lên\ntrong vị ấy giống như trường hợp của một kẻ phàm phu. Điều này do bởi\nnhững khuynh hướng đối với một hành vi nào đó đã lập đi lập lại trong\nnhững kiếp quá khứ của vị A-la-hán có liên quan ấy, mà trong vị ấy những\nkhuynh hướng ấy vẫn tồn tại như nghiệp lực còn sót lại, ngay cả sau khi\nđã đọan diệt tất cả phiền não.</p>\n<p>Một ví dụ về hiện tượng này được tìm thấy trong đại đức\nPilindavaccha, là một vị La hán sống trong thời kỳ của Đức Phật. Suốt\nnăm trăm kiếp liên tục, vị ấy sanh làm một vị Bà-la-môn của bộ tộc cao\nngạo. Những người trong bộ tộc ấy xem mọi người ngoài bộ tộc của họ là ”\nnhững kẻ vô lại”. Thói quen này ăn sâu trong vị ấy trải qua một chuỗi\nnhiều kiếp sống rất dài đến nỗi ngay sau khi trở thành bậc A-la-hán, vị\nấy không thể ngăn bản thân gọi tất cả những người khác dầu không cố ý –\nlà ” kẻ vô lại kia”. Sự xưng hô này không phải do ngã mạn về dòng dõi mà\nchỉ là hành động bị huân tập trong quá khứ mà thôi.</p>\n<ol start=\"3\" type=\"1\">\n<li><p>Arahaṁ có thể được diễn dịch là ” người mà không có nơi bí mật\nnào để làm điều ác” (a+raha). Có một số người tự cho mình là người có\ntrí tuệ hay đạo đức chỉ phô bày hình thức bên ngoài nhưng có khuynh\nhướng làm điều ác ở chỗ riêng tư. Đối với Đức Phật, vì Ngài đã đọan diệt\ntất cả phiền não một cách rốt ráo cùng với khuynh hướng về những hành\nđộng thuộc thói quen, cho nên không thể có nơi bí mật nào để Ngài làm\nđiều ác, Ngài cũng chẳng làm điều ác ở bất cứ nơi bí mật nào. Đức tánh\ncao quý là không có nơi bí mật nào để làm điều ác là đặc tánh của arahaṁ\nvà dòng Danh Sắc trong ngũ uẩn của Đức Phật là người sở hữu ân đức\nấy.</p></li>\n<li><p>Arahaṃ cũng có ý nghĩa là ” người đã bẻ gãy những chiếc căm mà\ntạo thành bánh xe sanh hữu” (ara+hata). Sanh hữu trong ba cõi - cõi Dục,\ncõi Sắc và cõi Vô sắc - được gọi một cách bóng bẩy là “chiếc xe của vòng\nsanh tử”. Sự sanh khởi liên tục của các uẩn (khandā), và các xứ\n(āyatana) và các giới (dhātu) được gọi một cách bóng bẩy là ” bánh xe\nsanh tử” là phần chính yếu của chiếc xe của vòng sanh tử. Trong bánh xe\nấy có vô minh và ái dục đối với kiếp sống là trục của bánh xe, trong khi\nnhững hành vi có tác ý thuộc phước hành (puññābhi-saṅkhāra) liên quan\nđến cõi Dục và cõi Sắc tạo thành những cái căm của bánh xe mà sanh lên\ntrong cõi Dục và cõi Sắc. Cũng vậy, những tác ý thuộc phi phúc hành\n(apuññābhi-saṅkhāra) mà tạo ra những ác nghiệp dẫn đến tái sanh bốn khổ\nthú (Apāya) tạo thành những cái căm của bánh xe mà sanh lên trong bốn\nkhổ cảnh. Cũng thế, những tác ý thuộc bất động hành (aneñjābhi-saṅkhāra)\nliên quan đến cõi Vô sắc tạo ra những việc phước hành thành những cái\ncăm của bánh xe mà sanh lên trong cõi Vô sắc.</p></li>\n</ol>\n<p>Trong sự sanh khởi ba loại nghiệp hành ấy, vô minh và ái dục đối với\nkiếp sống được gọi là trục của bánh xe, vì trục là nơi xuất phát sự quay\ncủa bánh xe, vì vậy mà hình thành nguyên nhân của vòng luân hồi. Sức\nmạnh của nó được truyền sang vành xe hoặc vỏ xe, nói một cách bóng bẩy,\nlà kết quả ( mà kết thúc ở già và chết), bởi những căm xe, tức là những\nnghiệp hành. Trong cách trình bày đầu tiên này, nguyên nhân chính về\nmười hai yếu tố của pháp Duyên khởi là Vô minh và Ái dục được cho thấy\nlà trục của bánh xe; già và chết được cho thấy vỏ bánh xe; và ba loại\nhành được cho thấy là những căm xe của bánh xe luân hồi. Những yếu tố\ncòn lại của pháp Duyên khởi được cho thấy là thân của chiếc xe sanh\ntử.</p>\n<p>Do sự hiện diện của các lậu hoặc (āsava) mà vô minh (avijjā) sanh\nkhởi. Vô minh có nguồn gốc hay nguyên nhân của nó trong các lậu hoặc.\nTheo đúng nghĩa, các lậu hoặc có thể được trông thấy là cái trục được\ngắn vào vòng trục vô minh và ái dục để vô minh sanh khởi.</p>\n<p>Như vậy, trong bánh xe luân hồi, với cái trục là các lậu hoặc được\nlắp vào vòng trục vô minh và ái dục đối với kiếp sống, với những căm xe\nthuộc ba loại hành và vỏ bánh xe là già và chết, mà được làm cho luân\nchuyển từ luân hồi không khởi điểm, tạo ra chiếc xe sanh tử trong ba\ncõi. Đức Phật, vào lúc Ngài chứng đắc Toàn Giác, đã phá vỡ những cái căm\ncủa bánh xe bằng cách đứng trên hai chân của sự tinh tấn của thân và\ntâm, đứng vững trong giới (sīla), và dùng bàn tay Đức tin nắm chắc cái\nbúa Đạo-Trí (magga-ñāṇa) (phước làm cạn kiệt kamma).</p>\n<p>Do đó sự bẻ gãy những cây căm của bánh xe luân hồi bằng cái búa của\nbốn Đạo-Trí là đặc tánh của arahaṁ; dòng Danh Sắc trong năm uẩn của Đức\nPhật là người sở hữu ân đức ấy.</p>\n<p>Một cách giải thích khác: Vòng sanh hữu không khởi đầu được gọi là\nvòng luân hồi. Vòng luân hồi này, nếu được xét trong ý nghĩa cùng tột,\nlà một bộ gồm mười hai yếu tố của pháp Duyên Khởi. Vô minh là nguồn gốc\nhay nguyên nhân của sự tái sanh là vòng trục của bánh xe. Già và chết là\nchỗ cuối của kiếp sống được nêu ra là vỏ của bánh xe. Vòng trục (vô\nminh) và vỏ bánh xe (già và chết) là hai đầu tận cùng của kiếp sống,\nmười yếu tố còn lại là những cái căm của bánh xe.</p>\n<p>Đức Phật đã hoàn toàn đọan diệt những cái căm của bánh xe luân hồi.\nDo đó sự phá tan mười mắc xích của pháp Duyên khởi bằng bốn nhát kiếm\ncủa Đạo-Trí (magga-ñāṇa) là ân đức của arahaṁ trong phần diễn dịch thứ\ntư này. Dòng trôi chảy Danh Sắc trong năm uẩn của Đức Phật là người sở\nhữu ân đức ấy.</p>\n<ol start=\"5\" type=\"1\">\n<li>Arahaṁ cũng có thể được diễn dịch là “Bậc đáng được sự tôn kính cúng\ndường của nhân loại, chư thiên và Phạm thiên.” Đức Phật là bậc cao quý\nnhất. Ngài xứng đáng thọ lãnh những sự cúng dường đặc biệt về bốn món\nvật dụng của vị Sa-môn bởi tất cả chúng sanh trong ba cõi. Đó là lý do\nmà khi Đức Phật sanh lên trong thế gian, thì chư thiên có đại uy lực và\nnhân loại không cúng dường lễ bái đến bất cứ ai khác ngoài Đức Phật.\nChúng ta hãy trích dẫn vài ví dụ quan trọng về ý nghĩa này: Phạm thiên\nSahampati cúng dường đặc biệt một bó hoa lớn bằng núi Tu-di đến Đức\nPhật. Chư thiên và những vị vua khác như Bimbisāra, Kosala, v.v… đã thực\nhiện những sự cúng dường to lớn nhất mà họ có thể làm được đến Đức Phật.\nHơn nữa, sau khi Đức Phật diệt độ, vua Asoka sử dụng chín mươi sáu koṭi\ntiền vàng để xây dựng tám mươi bốn ngàn tịnh xá khắp Nam thiện Bộ châu\ncủa xứ Diêm phù đề đểcúng dường Đức Phật.</li>\n</ol>\n<p>Do đó Giới (sīla), Định (samādhi), Tuệ (pañña), Giải thoát (vimutti)\nvà Giải thoát Tri kiến (vimutti ñāṇa dassana) vô song là những đức tánh\ncao quý làm cho Đức Phật xứng đáng thọ lãnh sự tôn kính cúng dường của\nnhân loại, chư thiên và Phạm thiên, tức là ân đức của Arahaṁ. Dòng Danh\nSắc trong năm uẩn của Đức Phật là bậc sở hữu ân đức ấy.</p>\n<p>(b) Không có khả năng làm điều ác, ngay cả khi không ai biết.</p>\n<p>(c) Đã bẻ gãy những cây căm của bánh xe sanh tử,</p>\n<p>(d) Đáng được lễ bái, cúng dường bởi tất cả chúng sanh trong ba cõi,\ngồm nhân loại, chư thiên và Phạm thiên.</p>"}, {"n": 2, "pali": "Sammāsambuddho", "paliUp": "SAMMĀ SAMBUDDHO", "vi": "Chánh Đẳng Chánh Giác", "short": "<p>Ngài hoàn toàn tự giác ngộ, trong đó Ngài biết như thật tất cả các\npháp bằng trí tuệ của Ngài và có khả năng thuyết giảng pháp cho tất cả\nchúng sanh.</p>", "detail": "<p>(Sammā: chân chánh, như thật; saṁ: tự mình; buddho: người biết được\ntất cả các pháp có thể biết được.) Đức Phật khám phá ra chân lý bằng tuệ\ngiác của chính Ngài mà không cần sự giúp đỡ của bất cứ ai. Chư Phật Bích\nchi (Paccekabuddha) cũng giác ngộ chân lý bằng chính tuệ giác của các\nngài. Tuy nhiên các ngài không thể giảng dạy chân lý mà các ngài đã giác\nngộ đến những người khác, nên các ngài không được danh hiệu\nSammāsambuddha. Các ngài chỉ được tôn là Saṃbuddha mà thôi. Các vị Thánh\nđệ tử (ariya) giác ngộ được chân lý chỉ nhờ sự giúp đỡ của một vị thầy\nnào đó và các ngài có khả năng thuyết giảng chân lý đến những người\nkhác, nhưng các ngài không tự mình giác ngộ chân lý nên các ngài cũng\nkhông được gọi là Sammāsambuddha. Các ngài chỉ được tôn là Sammābuddha.\nChư Phật là Saṁbuddha, người biết Chân lý và tất cả các pháp biết được\nbằng sự tự giác ngộ. Các Ngài cũng là Sammābuddha bởi vì các Ngài có thể\ngiảng dạy Tứ Diệu Đế đến chúng đệ tử từng người một theo khả năng tiếp\nthu của họ, và bằng ngôn ngữ mà họ có thể hiểu. Bởi vậy, sự kết hợp của\nhai đức tánh này làm chư Phật xứng đáng được danh hiệu Sammāsambuddha.\nDo đó, bốn đạo trí (magga-ñāṇa) mà khiến Đức Phật tự mình biết tất cả\ncác pháp bằng sự toàn tri ở mức cao nhất khiến ân đức này được gọi là\nSammāsambuddha. Dòng Danh sắc trôi chảy trong năm uẩn của Đức Phật là\nngười sở hữu ân đức ấy.</p>"}, {"n": 3, "pali": "Vijjācaraṇasampanno", "paliUp": "VIJJĀCARAṆA SAMPANNO", "vi": "Minh Hạnh Túc", "short": "<p>Có ba minh, đó là Túc mạng minh, Thiên nhãn minh và Lậu tận minh,\nBa loại minh này có thể mở rộng thành tám minh cùng với sự thực hành\nhoàn hảo về giới hạnh có thể định rõ trong mười lăm cách.</p>", "detail": "<p>Bậc có ba minh hoặc tám minh và mười lăm hạnh. Tam minh được Đức Phật\nthuyết giảng trong bài kinh Bhayabherava Sutta (Majjhima Nikāya,\nMullapaṇṇāsa), tám minh được Đức Phật thuyết giảng trong bài kinh\nAmbaṭṭha Sutta (Dīgha Nikāya). Hai cách thuyết giảng về minh trong ba\nloại và tám loại được chư Phật áp dụng do sự suy xét đầy bi mẫn về căn\ncơ của người nghe trong mỗi trường hợp.</p>\n<p><strong>Tam minh:</strong></p>\n<ol type=\"i\">\n<li><p>Túc mạng minh (pubbenivāsa-ñāṇa)</p></li>\n<li><p>Thiên nhãn minh (dibbacakkhu-ñāṇa)</p></li>\n<li><p>Lậu tận minh (āsavakkhaya-ñāṇa)</p></li>\n</ol>\n<p><strong>Bát minh:</strong></p>\n<ol type=\"i\">\n<li><p>đến (iii) ở phần trên và</p></li>\n<li><p>Quán minh (vipassanā-ñāṇa)</p></li>\n<li><p>Ý sở thành thần biến, Phân tâm minh (manomayiddhi-ñāṇa)</p></li>\n<li><p>Thần thông minh (iddhividha-ñāṇa)</p></li>\n<li><p>Thiên nhĩ minh (dibbasota-ñāṇa)</p></li>\n<li><p>Tha tâm minh (cetopariya-ñāṇa)</p></li>\n</ol>\n<p>(i) <strong>Túc mạng minh</strong> (pubbenivāsa-ñāṇa): Bằng loại minh\nnày, Đức Phật có thể trông thấy những kiếp quá khứ của chính Ngài và của\nchúng sanh khác.</p>\n<p>(ii) <strong>Thiên nhãn minh</strong>(dibbacakkhu-ñāṇa): Bằng minh\nnày, Đức Phật có thể trông thấy những vật ở rất xa, những vật bị che\nkhuất, và những vật rất tinh vi bé nhỏ đến nỗi mắt của người thường\nkhông thể nhìn thấy được.</p>\n<p>(iii) <strong>Lậu tận minh</strong> (āsavakkhaya-ñāṇa): Đây là\nA-la-hán Quả Trí diệt tắt tất cả bốn lậu hoặc.</p>\n<p>(iv) <strong>Quán minh</strong>(vipassanā-ñāṇa: sự thấy rõ tánh chất\nvô thường, khổ và vô ngã trong các pháp hữu vi thuộc Danh và Sắc.</p>\n<p>(v) <strong>Ý sở thành thần biến, Phân tâm minh</strong>\n(manomayiddhi-ñāṇa): Khả năng hoá hiện ra nhiều hình tướng khác nhau qua\nsự làm chủ cái tâm được thành tựu bởi sự đắc định.</p>\n<p>(vi)<strong>Thần thông minh</strong> (iddhividha-ñāṇa): Khả năng biến\nhoá số lượng lớn những hình tướng, hình người khác nhau hay cách khác\nnữa.</p>\n<p>(vii)<strong>Thiên nhĩ minh</strong> Thiên nhĩ minh (dibbasota-ñāṇa):\nKhả năng nghe các loại âm thanh từ những chỗ cách xa, những âm thanh bị\nngăn che hoặc những âm thanh rất vi tế mà tai của người thường không thể\nnghe được.</p>\n<p>(viii) <strong>Tha tâm minh</strong>(cetopariya-ñāṇa): Đức Phật có\nthể biết được tâm của những kẻ khác bằng mười sáu cách. Trong tám loại\nminh kể trên:</p>\n<ul>\n<li><p>Quán minh là trí thuộc về dục giới.</p></li>\n<li><p>Lậu tận minh là loại trí siêu thế gian.</p></li>\n<li><p>Sáu loại minh còn lại thuộc về cõi Sắc những năng lực của thiền\nđược gọi là rūpāvacara kriyā abhiññā ñāṇa.</p></li>\n</ul>\n<p><strong>Mười lăm hạnh (Carana)</strong></p>\n<ol type=\"i\">\n<li><p>Giới luật nghi (sīla saṇvara)</p></li>\n<li><p>Căn luật nghi (indriyesugutta dvāratā)</p></li>\n<li><p>Thực tri lượng (bhojane matanutā)</p></li>\n<li><p>Sự giác tỉnh (jāgariyā nuyoga)</p></li>\n</ol>\n<blockquote>\n<p>(v-xi) Bảy đức tánh của những bậc giới đức.</p>\n<p>(xii-xv) Bốn thiền hữu sắc.</p>\n</blockquote>\n<ol type=\"i\">\n<li><p><strong>Giới luật nghi</strong> (sīla saṇvara): Sự thọ trì các\nhọc giới của vị tỳ khưu, Pāṭimokkha Saṇvara sīla.</p></li>\n<li><p><strong>Căn luật nghi</strong> (indriyesugutta dvāratā): Sự hộ\nphòng các môn gồm: mắt, tai, mũi, lưỡi, thân và ý bằng chánh niệm liên\ntục để không cho bất cứ ác pháp nào đi vào.</p></li>\n</ol>\n<!-- -->\n<ol start=\"4\" type=\"i\">\n<li><p><strong>Thực tri lượng</strong> (bhojane matanutā): Biết mức độ\nvừa phải trong sự thọ lãnh vật thực và trong sự thọ dụng nó. Trong sự\nthọ lãnh vật thực, Đức Phật xem xét mức độ tịnh tín của người thí chủ.\nNếu tâm tịnh tín mạnh mà vật thí nhỏ, thì Đức Phật không xem thường tính\nchất nhỏ của vật thí mà vẫn thọ lãnh nó. Trái lại, nếu vật thí lớn nhưng\ntâm tịnh tín của người thí chủ yếu, thì Đức Phật chỉ thọ lãnh một lượng\nnhỏ vật thực mà thôi. Nếu vật thí lớn và tâm tịnh tín của thí chủ mạnh,\nthì Đức Phật thọ nhận một lượng thích hợp để thỏa mãn nhu cầu của Ngài.\nĐây được gọi là tri túc trong vật thực. Khi độ vật thực đã được thọ lãnh\nnhư vậy, Đức Phật không bao giờ ăn đến đầy bụng mà dừng lại khi còn bốn\nhoặc năm miếng nữa mới đầy bụng. Quan trọng hơn là Ngài không bao giờ ăn\nmà không quán tưởng.</p></li>\n<li><p><strong>Sự giác tỉnh</strong> (jāgariyā nuyoga): Tỉnh giác không\nchỉ có nghĩa là không ngủ. Đức Phật trải qua suốt ngày, canh đầu và canh\ncuối của đêm trong pháp thiền, trong khi đang đi hoặc ngồi, nhờ vậy mà\nxa lìa các pháp chướng ngại. Sự tỉnh thức có chủ tâm như vậy được gọi là\ntỉnh giác. Trong hai mươi bốn giờ của một ngày, Đức Phật chỉ ngủ bốn giờ\n- khoảng thời gian từ 10 giờ tối đến 2 giờ sáng để phục hồi năng lượng\ncủa Ngài; hai mươi giờ còn lại Ngài sống trong pháp thiền và thực hành\nphận sự của vị sa-môn.</p></li>\n</ol>\n<p><strong>(v đến xi) Bảy đức tánh của những bậc Giới đức:</strong></p>\n<p>(v) Niềm tin trong Tam bảo (saddhā)</p>\n<p>(vi) Chánh niệm (sati)</p>\n<p>(vii) Tàm - cảm giác xấu hổ với điều ác (hirī)</p>\n<p>(viii) Quý- cảm giác ghê sợ điều ác (ottapa)</p>\n<p>(ix) Đa trí - học rộng về giáo pháp (bāhusacca)</p>\n<p>(x) Tinh tấn (vīriya)</p>\n<p>(xi) Trí tuệ (pañña)</p>\n<p><strong>(xii-xv) Bốn Thiền Hữu sắc:</strong> ám chỉ bốn tầng Thiền\nHữu sắc, từ sơ thiền đến tứ thiền.</p>\n<p>Mười lăm hình thức thực hành hoàn hảo về giới hạnh đạo đức kể trên đi\nthẳng đến Niết bàn, mà những Thinh văn đệ tử khi còn phàm phu trước đó\nchưa bao giờ giác ngộ được. Thế nên chúng được gọi là Hạnh - Caraṇa.</p>\n<p>Minh (vijjā) và Hạnh (caraṇa) bổ sung cho nhau. Minh giống như đôi\nmắt trong khi đó Hạnh giống như hai chân. Để đến được chỗ mong muốn, đôi\nmắt mà thiếu hai chân thì không thể thành tựu được và ngược lại, hai\nchân cũng vậy, không thể đến được nếu không có đôi mắt. Do đó, Minh và\nHạnh nên được cùng tu tập. Có thể nêu ra câu hỏi rằng “Phải chăng các\nThánh đệ tử (ariya) không thể chứng đắc được Minh và Hạnh?” Câu trả lời\nlà phải và không phải. Các bậc thánh có thể chứng đắc chúng nhưng các\nngài không thể được xem là có Ân đức của Minh Hạnh túc mà vốn thuộc về\nriêng Đức Phật vì những lý do được nêu ra dưới đây:</p>\n<p>Có hai yếu tố trong ân đức này, được thành tựu về Minh, và được thành\ntựu về Hạnh. Sự thành tựu về Minh của Đức Phật là nguồn gốc của sự Toàn\ntri. Sự thành tựu về Hạnh của Ngài là nguồn gốc để Ngài trở thành bậc\nĐại bi. Do được thành tựu trong hai cách như vậy, Đức Phật bằng trí tuệ\ncủa Ngài biết được điều gì có lợi ích cho mỗi chúng sanh và điều gì\nkhông có lợi ích. Hơn nữa Đức Phật, qua Hạnh của Ngài, Ngài mở rộng lòng\nbi mẫn đến tất cả chúng sanh để khiến họ tránh xa điều gì không có lợi\ních cho họ và thực hành những điều đem đến lợi ích cho họ. Do vậy, sự\nthành tựu về Minh và Hạnh của Ngài cùng làm cho Giáo lý của Ngài trở\nthành Giáo pháp giải thoát.</p>\n<p>Nó cũng bảo đảm cho những đệ tử của Ngài rằng sự tu hành của họ là\nchân chánh, là sự tu hành đúng đắn. Vì thế, sự thành tựu về Minh và Hạnh\nđược gọi chung là ân đức của Minh Hạnh Túc, Vijjācaraṇa sampanno. Dòng\nDanh Sắc trong năm uẩn của Đức Phật là người sở hữu ân đức\nấy<em>.</em></p>"}, {"n": 4, "pali": "Sugato", "paliUp": "SUGATO", "vi": "Thiện Thệ", "short": "<p>Bởi vì Đức Phật đi đến Niết-bàn bằng bốn đạo trí (magga-ñāṇa),\nĐức Phật chỉ nói điều gì chân thực và có lợi ích.</p>", "detail": "<p>Chú giải giải thích ân đức này qua bốn cách:</p>\n<ol type=\"a\">\n<li><p><em>Su</em>: thiện; <em>gata:</em> đã đi đến. Sự đi đến như vậy,\ntức là sự chứng đắc Thánh đạo, cho nên ” Bậc đã chứng đắc các Thánh đạo”\nlà ý nghĩa thứ nhất: Thánh đạo nghĩa là không lỗi lầm và vì vậy là cao\nthượng. Đức Phật được gọi là <em>Sugata</em> vì Ngài đi đến chỗ an toàn\nthoát khỏi mọi nguy hiểm, bằng Đạo cao thượng. ( Trong sự diễn dịch này,\nthì Thánh đạo là ân đức và dòng danh Sắc trôi chảy trong năm uẩn của Đức\nPhật là người sở hữu ân đức ấy).</p></li>\n<li><p><em>Su</em>: Niết bàn mục tiêu tối thắng; <em>gata:</em> đi đến\nđó bằng trí tuệ. Niết bàn là mục tiêu tối thắng vì Niết bàn là chỗ chấm\ndứt mọi phiền khổ và là sự an lạc tuyệt đối. Đạt đến mục tiêu tối thắng\nấy bằng Đạo-trí (<em>magga-ñāṇa</em>) là ân đức của Đức Phật. (Ở đây\nThánh đạo là ân đức, còn dòng danh sắc trong năm uẩn của Đức Phật là\nngười sở hữu ân đức ấy.) Trong cả hai sự diễn dịch này, sự đi đến Niết\nbàn nghĩa là lấy Niết bàn làm đối tượng của tâm. Sự đi đến ở đây chỉ có\nnghĩa là trí tuệ, chứ không phải ý nghĩa về hành vi của thân đi đến một\nđịa điểm nào đó.</p></li>\n<li><p><em>Su</em>: <em>Sammā</em> chân chánh; <em>gata</em>: đi đến\nNiết bàn bằng Đạo-trí (<em>magga-ñāṇa)</em>. Ở đây, chữ ‘chân chánh’ chỉ\nvề sự giải thoát khỏi mọi ô nhiễm. Sự đi đến chân chánh bởi vì các pháp\nô nhiễm bị đọan diệt bởi bốn Đạo-trí không còn sanh khởi trong Đức Phật\nnữa. Trong tất cả ba cách diễn dịch ở trên, ý nghĩa rốt ráo giống nhau:\nLấy Niết bàn làm đối tượng của tâm qua bốn Đạo Trí. Đây là cách giải\nthích thứ nhất về <em>Sugata</em> trong ý nghĩa tóm tắt được nêu ra ở\ntrước.</p></li>\n<li><p><em>Su: sammā</em>, khéo tốt; <em>gata</em>: nói một cách thích\nđáng trong những dịp thích hợp. Ở đây <em>gada</em> là căn gốc được đổi\nthành <em>gata</em>. Sự nói thích hợp hay khéo nói được giải thích thêm\nnhư vầy: “Có sáu loại lời nói trong mọi người; trong sáu loại này, bốn\nloại nên được từ bỏ tức là không được dùng đến, và chỉ có hai loại lời\nnói nên được sử dụng.”</p></li>\n</ol>\n<!-- -->\n<ol type=\"i\">\n<li><p>Có loại lời nói không đúng sự thực, không có lợi ích và không\nđược người khác ưa thích (ví dụ: nói rằng người thiện trí là xấu ác.).\nĐức Phật tránh xa loại lời nói này.</p></li>\n<li><p>Có loại lời nói đúng sự thực nhưng không có lợi ích và không được\nchấp nhận bởi người khác. (Ví dụ: gọi một người ác là người ác, không có\ný định giúp người ấy từ bỏ điều sai, mà nói với ác ý). Đức Phật tránh xa\nloại lời nói này.</p></li>\n<li><p>Có loại lời nói đúng sự thực, có lợi ích nhưng người ta không\nthích nghe. (Ví dụ: khi nói đến Devadatta là người đang hướng đến địa\nngục - được Đức Phật tiên tri do lòng bi mẫn đối với vị ấy). Đức Phật\nnói loại lời nói này khi có dịp mới cần phải nói.</p></li>\n<li><p>Có loại lời nói không đúng sự thực, không đem lại lợi ích cho\nngười khác nhưng người vẫn thích nghe. (Ví dụ: khi trích dẫn từ kinh\nVeda người ta khẳng định rằng hành động ác như sát sanh sẽ dẫn đến tái\nsanh thiện thú). Đức Phật cũng tránh loại lời nói này.</p></li>\n<li><p>Có loại lời nói đúng sự thực nhưng không đem lợi ích cho người\nkia, nhưng người ta vẫn thích nghe. (Ví dụ: một lời tuyên bố đúng sự\nthật mà sẽ gây chia rẽ giữa hai phe). Đức Phật cũng tránh xa loại lời\nnói này.</p></li>\n<li><p>Có loại lời nói đúng sự thực, có lợi cho người nghe, và người kia\ncũng thích nghe. (Ví dụ: sự thuyết pháp về bố thí, trì giới, v.v… được\nthuyết giảng đúng trường hợp). Đức Phật nói loại lời nói này khi có cơ\nhội thích hợp.</p></li>\n</ol>\n<blockquote>\n<p>Từ sáu loại lời nói kể trên, Đức Phật chỉ sử dụng loại thứ ba và thứ\nsáu mà thôi.</p>\n<p>Xét về loại thứ ba ở trên, nếu một câu nói chân thực và có lợi ích\ncho người nghe, dầu người ấy không thích nghe nó, Đức Phật cũng nói ra\nbởi vì nó có lợi ích cho những người mà nghe nó và sẽ đem lại lợi ích\ncho toàn thể thế gian.</p>\n<p>Như vậy, nếu một câu nói chân thật và đem lại lợi ích cho người nghe,\nthì Đức Phật vẫn nói ra dầu người nghe có thích hay không. Do đó, Đức\nPhật được gọi là <em>Sugata</em> (Thiện thệ), Ngài nói lời chân thật và\ncó lợi ích. Nói về điều gì có lợi ích và chân thực là Ân đức, và dòng\ndanh sắc trôi chảy trong năm uẩn của Đức Phật là người sở hữu ân đức\nấy.</p>\n</blockquote>"}, {"n": 5, "pali": "Lokavidū", "paliUp": "LOKAVIDŪ", "vi": "Thế Gian Giải", "short": "<p>Bởi vì Ngài biết sự sanh khởi có điều kiện (do nhân duyên) của\ntất cả chúng sanh, những nền tảng của chúng trong nhiều cõi khác nhau,\nvà tánh chất có điều kiện của các pháp thuộc Danh và Sắc.</p>", "detail": "<p><em>Loka</em>, năm thủ uẩn hay năm uẩn được chấp thủ\n(<em>upādānakkhandhā</em>); (trong một nghĩa khác), hữu tình thế gian\n(<em>satta-loka</em>), hành thế gian hay thế giới hữu vi pháp\n(<em>saṅkhāra-loka</em>), không gian thế gian hay thế giới làm nền tảng\ncho nhiều cõi sanh hữu (<em>okāsaloka</em>). <em>Ví dụ</em> người có trí\ntuệ phân tích và có sự hiểu biết hoàn toàn.</p>\n<p>Bộ Visuddhimagga giải thích chữ <em>lokavidū</em> bằng hai cách:</p>\n<p>(1) Trong cách thứ nhất, <em>loka</em> được diễn dịch là năm uẩn được\nchấp thủ gọi là năm thủ uẩn. Năm uẩn này được hiểu:</p>\n<p>(a) là khổ (<em>dukkha</em>),</p>\n<p>(b) có nguồn gốc ở ái dục (<em>taṇhā</em>),</p>\n<p>(c) sự diệt tắt khi Niết bàn được giác ngộ,</p>\n<p>và (d) Thánh đạo là con đường chân chánh dẫn đến Niết bàn, sự chấm\ndứt các uẩn. Như vậy <em>lokavidū</em> nghĩa là Đức Phật có sự hiểu biết\nđầy đủ về năm thủ uẩn.</p>\n<p>Trong việc biết về thế giới của năm thủ uẩn, Đức Phật không chỉ biết\nvề năm thủ uẩn không thôi mà còn biết chúng trong bốn phương diện làm\ncho trí tuệ của Ngài được hoàn hảo. Bốn phương diện ấy là:</p>\n<p>(a) Ngài biết rằng năm thủ uẩn là thật sự khổ (<em>dukkha</em>);</p>\n<p>(b) Ngài biết về phương diện nguồn gốc của năm uẩn này - ái dục là\nnguồn gốc của năm uẩn;</p>\n<p>(c) Ngài biết rõ Niết bàn, phương diện chấm dứt của năm uẩn;</p>\n<p>(d) Ngài biết con đường dẫn đến sự chấm dứt, tức là Thánh đạo. Như\nvậy Đức Phật có sự hiểu biết hoàn toàn về năm thủ uẩn. Đó là lý do khiến\nĐức Phật được gọi là <em>Lokavidū</em>. Trong phương pháp diễn dịch thứ\nnhất, trí tuệ hiểu biết hoàn toàn từ bốn phương diện của năm thủ uẩn là\nân đức <em>Lokavidū</em>. Năm uẩn của Đức Phật là người sở hữu ân đức\nấy.</p>\n<p>(2) Dầu phương pháp diễn dịch thứ nhất đã đầy đủ về thế giới năm uẩn,\nnhưng phương pháp ấy mô tả chữ <em>Loka</em> chưa đầy đủ. Do đó Chú giải\nnêu ra cách diễn dịch thứ hai.</p>\n<p>Trong cách thứ hai thì Loka có ý nghĩa là thế giới hữu tình hay hữu\ntình thế gian (<em>satta-loka</em>), hành thế gian\n(<em>saṅkhāra-loka</em>) và không gian thế gian (<em>okāsa-loka</em>).\nLoka nghĩa là cái gì có sanh và có diệt, chịu sự sanh diệt. Theo quan\nđiểm Abhidhamma, thì các uẩn của chúng sanh hữu tình được gọi là căn\nphược uẩn (<em>indriyabaddha-khandhā</em>). Các uẩn của vô tình chúng\nsanh được gọi là phi căn phược uẩn\n(<em>anindriyabaddha</em>-<em>khandhā</em>).</p>\n<p>(a) Các uẩn của chúng sanh hữu tình có khả năng bị luyến ái theo cảnh\nsắc, cảnh thinh, v.v… cho nên được gọi là hữu tình (<em>satta</em>). Vì\nnhững uẩn này tạo thành nền tảng cho phước và tội sanh và diệt. Nên\nchúng cũng được gọi là thế gian (loka). Như vậy chúng ta có từ Hữu tình\nthế gian (<em>satta-loka</em>).</p>\n<p>(b) Các uẩn của chúng sanh vô tình như những hệ thống thế giới vô\nbiên (<em>cakkavaḷā</em>), những nền tảng cho đời sống hữu tình\n(<em>bhūmi</em>, địa) và những toà nhà, v.v… là những nền tảng nơi mà\nchúng sanh hiện diện, dầu họ còn bị sợ hãi như trong trường hợp của\nnhững kẻ phàm phu, những bậc Nhập lưu và Nhất lai, hay đã thoát khỏi sợ\nhãi như trường hợp những bậc Bất lai và A-la-hán, và được gọi là không\ngian (<em>Okāsa</em>). Và vì những nền tảng này là những chỗ mà những\nchúng sanh hữu tình sanh lên và diệt mất, nên chúng được gọi là\n<em>loka</em>. Như vậy chúng ta có từ Không gian thế gian\n(<em>okāsa-loka</em>).</p>\n<p>(c) Cả chúng sanh hữu tình lẫn vô tình đều do những nguyên nhân làm\nduyên sanh nên được gọi là Hành (<em>saṅkhāra</em>). Thế giới phải chịu\nsự sanh diệt, nên được gọi là thế gian (<em>loka</em>). Như vậy chúng ta\ncó từ Hành thế gian (<em>saṅkhāra-loka</em>). Đức Phật hiểu biết hoàn\ntoàn Hành thế gian.</p>\n<p>Chúng ta sẽ mở rộng vấn đề này như đã được giải thích trong\nVisuddhimagga: “<em>Eko loko sabbe sattā āhāraṭhitikā</em>. – Tất cả\nchúng sanh bản thân đều có những yếu tố làm duyên sanh; đây là thế gian\ntrong chính nó” (<em>paṭisambhidā-magga</em> được trích ra ở đây). Do\nđó,</p>\n<p><em>loka</em> ở đây nghĩa là <em>Saṅkhāra-loka</em> (hành thế gian).\n(Bởi vì mặc dù chúng sanh được xét đến, nhưng điểm cốt yếu ở đây là tánh\nchất duyên sanh đang tạo ra sự sanh diệt trong tất cả chúng sanh).</p>\n<p>Đức Phật có sự hiểu biết đầy đủ về thế giới hữu vi mà trong đó Ngài\nbiết nó</p>\n<p>(1) là một yếu tố tạo ra tất cả các pháp hữu vi;</p>\n<p>(2) là hai pháp hữu vi, Danh và Sắc;</p>\n<p>(3) là ba pháp hữu vi trong ba loại thọ;</p>\n<p>(4) là bốn pháp hữu vi trong bốn yếu tố làm duyên,\n<em>āhāra</em>;</p>\n<p>(5) là năm pháp hữu vi trong năm thủ uẩn;</p>\n<p>(6) là sáu pháp hữu vi trong sáu nội xứ;</p>\n<p>(7) là bảy pháp hữu vi trong bảy trạm của thức;</p>\n<p>(8) là tám pháp hữu vi trong tám pháp thế gian;</p>\n<p>(9) là chín pháp hữu vi trong chín chỗ trú của chúng sanh;</p>\n<p>(10) là mười pháp hữu vi trong mười sắc xứ;</p>\n<p>(11)là mười hai pháp hữu vi trong mười hai xứ;</p>\n<p>(12) là mười tám pháphữu vi trong mười tám giới.</p>\n<p>Cũng như Đức Phật có sự hiểu biết hoàn toàn về thế giới hữu vi, Ngài\ncũng biết đầy đủ về thế giới hữu tình, trong đó (a) <em>āsaya,</em> Ngài\nbiết các khuynh hướng của chúng sanh, (b) <em>anusaya,</em> Ngài biết\nnhững khuynh hướng ngủ ngầm trong chúng sanh, pháp tùy miên, (c)\n<em>carita</em>, Ngài biết tánh khí của chúng sanh, (d)\n<em>adhimutti</em>, Ngài biết những thiên hướng của chúng sanh. Ngài\nbiết những chúng sanh có ít bụi phiền não trong con mắt trí tuệ của họ,\nvà Ngài biết những chúng sanh có nhiều bụi phiền não trong con mắt trí\ntuệ của họ. Ngài biết những chúng sanh có các căn nhạy bén như Tín, và\nNgài biết những chúng sanh có các căn trì độn. Ngài biết những chúng\nsanh có ước muốn tự nhiên về sự giải thoát và những chúng sanh có ít ước\nmuốn giải thoát.</p>\n<p>Ngài biết những chúng sanh có những pháp chân chánh như đức tin và\ntrí tuệ mà giúp họ dễ dàng chứng đắc Đạo trí, và những chúng sanh không\ncó những pháp chân chánh như vậy. Ngài biết những chúng sanh đã thoát\nkhỏi những chướng ngại trong những hành vi quá khứ, những phiền não mà\nngăn chặn sự chứng đắc Đạo trí và những chúng sanh chưa thoát khỏi những\nchướng ngại như vậy.</p>\n<p><strong>(a) <em>Āsaya</em> - Các khuynh hướng.</strong></p>\n<p><em>Āsaya</em> nghĩa là khuynh hướng của chúng sanh. Ví dụ: con nai\nrừng có khuynh hướng tự nhiên là thích sống trong rừng; nó có thể đi đến\nnhững cánh đồng để ăn cỏ nhưng trú xứ của nó vẫn là khu rừng.</p>\n<p>Tương tự, những chúng sanh tiếp xúc nhiều cảnh trần khác nhau, nhưng\nsau khi trôi lăn từ cảnh này đến cảnh khác thì tâm của những người mà có\nkhuynh hướng muốn trôi lăn trong vòng sanh hữu thì ở trong tà kiến,\ntrong khi tâm của những người có khuynh hướng nghiêng về giải thoát khỏi\nvòng sanh tử luân hồi, thì thanh tịnh và ở trong trí tuệ. Bởi vậy tà\nkiến và trí tuệ được gọi là <em>āsaya</em>, khuynh hướng.</p>\n<p>Khuynh hướng tà kiến, <em>diṭṭhiāsaya</em> lại chia ra làm hai loại:\nkhuynh hướng về đọan kiến (<em>uccheda-diṭṭhi</em>) và khuynh hướng về\nthường kiến (<em>sassata-diṭṭhi</em>).</p>\n<p>Khuynh hướng trí tuệ, <em>paññā-āsaya</em> cũng có hai loại: Tuệ quán\ndẫn đến Đạo trí, <em>vipassanā paññā-āsaya</em>, và chính Đạo trí là trí\ntuệ thấy các pháp như thật, <em>yathābhuta ñāṇa-āsaya</em>.</p>\n<p>Về trí tuệ biết rõ các khuynh hướng của chúng sanh, Đức Phật biết\nrằng:</p>\n<ol type=\"i\">\n<li><p>chúng sanh này có khuynh hướng thích trôi lăn trong vòng sanh tử\nvà có khuynh hướng về đọan kiến;</p></li>\n<li><p>chúng sanh này có khuynh hướng trôi lăn trong luân hồi và có\nkhuynh hướng về thường kiến.</p></li>\n<li><p>chúng sanh này có khuynh hướng nghiêng về sự giải thoát khỏi vòng\nsanh tử, một kẻ thanh tịnh, và có Tuệ quán;</p></li>\n<li><p>và chúng sanh này có khuynh hướng nghiêng về sự giải thoát khỏi\nvòng sanh tử và có Đạo trí.</p></li>\n</ol>\n<p><strong>(b) <em>Anusaya</em> - Tuỳ miên</strong></p>\n<p>Đây là những phiền não mà chưa được đọan diệt bởi Đạo trí\n(<em>magga-ñāṇa</em>) và có khả năng sanh lên bất cứ khi nào có cơ hội\nthích hợp. Những phiền não ngủ ngầm này có bảy loại. Chúng được gọi là\npháp ngủ ngầm. Đó là:</p>\n<ol type=\"i\">\n<li><p>Dục tham tùy miên (<em>kāmarāgānusaya</em>),</p></li>\n<li><p>Hữu ái tùy miên (<em>bhavarāgānusaya</em>),</p></li>\n<li><p>Sân tùy miên (<em>paṭighānusaya</em>),</p></li>\n<li><p>Mạn tùy miên (<em>mānānusaya</em>), (v) Kiến tùy miên\n(<em>diṭṭhānusaya</em>),</p></li>\n<li><p>Nghi tùy miên (<em>vicikicchānusaya</em>), (vii) Vô minh tùy miên\n(<em>avijjānusaya</em>).</p></li>\n</ol>\n<p>Về việc biết các pháp tùy miên của chúng sanh, Đức Phật biết: chúng\nsanh này có nhiều Dục tham tùy miên; chúng sanh này có nhiều Hữu ái tùy\nmiên; chúng sanh này có nhiều Sân tùy miên; chúng sanh này có nhiều Mạn\ntùy miên; chúng sanh này có nhiều Tà kiến tùy miên; chúng sanh này có\nnhiều Nghi tùy miên; chúng sanh này có nhiều Vô minh tùy miên.</p>\n<p>Phiền não tùy miên <em>(anusaya kilesa)</em>, nên được chú ý là có ba\nmức độ tùy theo khuynh hướng xuất hiện của nó:</p>\n<p>(i) phiền não ngủ ngầm;</p>\n<p>(ii) phiền não đã thực sự sanh lên với ba giai đọan của chúng là sanh\n(<em>upāda</em>), trụ là phát triển hay hiện hữu tạm thời\n(<em>ṭhīti</em>), và diệt (<em>bhaṅga</em>);</p>\n<p>(iii) phiền não đã bộc phát thành hành vi bất thiện về thân hoặc lời\nnói. (Chúng ta hãy chứng minh điều này)</p>\n<p>Giả sử có một người phàm phu nào đó đang bố thí cúng dường mà trong\nanh ta những phiền não chưa được đọan tận bởi Đạo trí. Mặc dầu trong lúc\nlàm các việc phước, các tâm đại thiện (<em>mahā-kusala</em>\n<em>citta</em>) đang sanh khởi trong tâm của anh ta nhưng nếu anh ta\ntình cờ tiếp xúc một cảnh khả ái nào đó, trường hợp này có khuynh hướng\nlàm trổi dậy những ý nghĩ dục tham trong dòng tâm của người thí chủ vì\ncòn là phàm phu, anh ta chưa đọan tận dục tham. Hơn nữa, khi tiếp xúc\nvới cảnh mà đối với anh ta là khả ái thì dục tham tùy miên sẽ sanh lên\nthành những ý nghĩ bị ô nhiễm rõ rệt gọi là Triền phiền não -\n<em>pariyutthāna kilesa</em>. Khi ấy nếu anh ta chế phục nó bằng Như lý\ntác ý, thì những ý nghĩ bị ô nhiễm bởi tham có thể lắng xuống. Tuy\nnhiên, nếu thay vì có Như lý tác ý, anh ta để tâm bị hút vào Bất như lý\ntác ý, thì những ý nghĩ bị ô nhiễm sẽ chuyển thành những hành động bất\nthiện, hoặc bằng thân hoặc bằng lời nói. Đây là giai đọan bộc phát của\ndục tham phiền não, vi phạm phiền não - <em>vītikkama kilesa</em>. Đây\nlà ví dụ về cách mà dục tham phiền não trỗi dậy từ trạng thái ngủ ngầm\ncủa nó sang các hành vi rõ rệt trong ba giai đọan của nó. Những phiền\nnão khác như sân, v.v… cũng xảy ra tương tự như vậy.</p>\n<p><strong>(c) <em>Carita</em> - Tánh hạnh</strong></p>\n<p><em>Carita</em> nghĩa là hành động thiện hoặc bất thiện. Trong một ý\nnghĩa khác, nó ám chỉ sáu loại tánh hạnh thường hay xảy ra trong đời\nsống hiện tại, đó là tham (<em>rāga</em>), sân (<em>dosa</em>), si\n(<em>moha</em>), niềm tin (<em>saddhā)</em>, giác (<em>buddhi</em>), và\ntầm cầu (<em>vitakka</em>). ( Hai từ pali <em>carita</em> và\n<em>vāsanā</em> phải được phân biệt rõ. Ấn tượng mập mờ về những hành vi\nquen thuộc, dù thiện hay bất thiện, trong những kiếp quá khứ mà vẫn còn\ndai dẳng cho đến kiếp sống hiện tại thì được gọi là <em>vāsanā</em>.\nLoại tánh hạnh, cả sáu loại kể trên, là loại mà có khuynh hướng xảy ra\ntrong hầu hết thời gian của kiếp sống hiện tại thì được gọi là\n<em>carita</em> - tánh hạnh.)</p>\n<p>Đức Phật biết tánh hạnh của mỗi cá nhân như: người này có tánh thiện\n(<em>sucarita</em>); người này có tánh ác (<em>ducarita</em>); người này\ncó tán tham (<em>rāga-carita</em>); người này có tánh sân\n(<em>dosa-carita</em>); người này có tánh si (<em>moha-carita</em>);\nngười này có tánh dễ tin (<em>saddhā-carita</em>); người này có tánh\ngiác (<em>buddhi carita</em>); người này có tánh tầm cầu\n(<em>vitakkacarita</em>). Hơn nữa, Đức Phật cũng biết bản chất của sáu\nloại tánh hạnh ấy, những nhân duyên gây ô nhiễm, những nhân duyên làm\nthanh tịnh, những nhân duyên nòng cốt, những kết quả, và những hậu quả\ndẫn theo của sáu loại tánh hạnh ấy.</p>\n<p><strong>(d) <em>Adhimutti</em></strong></p>\n<p>Adhimutti nghĩa là khuynh hướng tự nhiên của chúng sanh. Có hai loại\n<em>adhimutti</em>, đó là sở thích tự nhiên về điều ác\n(<em>hīnadhi-mutti</em>), và sở thích tự nhiên nghiêng về những pháp cao\nquý (<em>paṇītadhi-mutta</em>).</p>\n<p>Thông thường mọi người kết thân với những người có cùng tánh khí;\nnhững người có tánh khí ác thì kết thân với những người có tánh khí ác;\nnhững người có tánh khí cao thượng thì thích kết thân với những người có\ntánh khí cao thượng.</p>\n<p>Đức Phật biết loại tánh khí trong mỗi chúng sanh, hoặc là người có\ntánh ác hay có tánh cao thượng.</p>\n<p>Hơn nữa, Đức Phật biết mức độ của tánh khí trong mỗi chúng sanh, hoặc\nlà mạnh, hoặc trung bình, hoặc yếu. Vì khuynh hướng tùy thuộc vào mức độ\nmạnh yếu của đức tin, sự tinh tấn, niệm, định và tuệ, đó là Ngũ căn.</p>\n<p>Như vậy Đức Phật có sự hiểu biết hoàn toàn về chúng sanh về bốn\nkhuynh hướng (<em>āsaya</em>), bảy pháp tùy miên (<em>anusaya</em>); ba\nnghiệp hành (<em>abhisaṅkhāra</em>) hay sáu loại tánh (<em>carita</em>),\nvà những khuynh hướng tự nhiên (<em>adhimutti</em>).</p>\n<p>Đức Phật có sự hiểu biết hoàn về thế giới hữu tình như thế nào thì\nNgài cũng có sự hiểu biết hoàn toàn về thế giới vô tình – là những nơi\nchốn mà chúng sanh trú ngụ như hệ thống thế giới (<em>cakkavāḷa</em>),\nlâu</p>\n<p>đài, nhà cửa, núi rừng, v.v...</p>\n<p>Đây là sự giải thích: Một hệ thống thế giới được gọi là\n<em>Cakkavāḷa</em> hay <em>Lokadhātu</em> được bao quanh bốn hướng bởi\nnhững ngọn núi cao như hàng rào bằng đá. (<em>cakka</em>: vòng tròn;\n<em>vāḷa</em>: vòng núi bao quanh). Sở dĩ người ta gọi\n<em>Cakkavāḷa</em> bởi vì nó là một hệ thống thế giới được bao quanh bởi\nnhững ngọn núi đá. Mỗi hệ thống thế giới có bề rộng 1.203.450 (một triệu\nhai trăm lẻ ba ngàn, bốn trăm năm mươi do tuần (<em>yojanā</em>) từ đông\nsang tây, và từ nam đến bắc. Chu vi của hệ thống thế giới này là\n3.610.350 (ba triệu sáu trăm mười ngàn, ba trăm năm mươi ) do tuần.</p>\n<p>Trong một hệ thống thế giới, bề dày của quả đất là 240.000 (hai trăm\nbốn chục ngàn) do tuần, nửa trên của nó là đất và nửa dưới của nó cấu\ntrúc bằng đá.</p>\n<p>Quả đất được nâng đỡ bởi một khối nước khổng lồ dày 480.000 (bốn trăm\ntám chục ngàn) do tuần. Bên dưới khối nước có khối không khí dày 960.000\n(chín trăm sáu chục ngàn) do tuần nâng đỡ nó. Và bên dưới khối không khí\nlà khoảng hư không vô biên. Đây là cấu trúc thành lập một hệ thống thế\ngiới.</p>\n<p>Ở trung tâm bề mặt của quả đất có mọc lên ngọn núi Sineru, phần dưới\ncủa nó chìm trong đại dương sâu 84.000 (tám mươi bốn ngàn) do tuần và\nnổi lên khỏi mặt nước với bề cao 84.000 (tám mươi bốn ngàn) do tuần.</p>\n<p>(1) Bao quanh ngọn núi Sineru, có một vòng núi có tên là Yugandhara,\nmột nửa của nó chìm trong đại dương với bề sâu 42.000 (bốn mươi hai\nngàn) do tuần và nửa phần trên thì nổi trên mặt đại dương cao 42.000 do\ntuần.</p>\n<p>(2) Ở bên ngoài dãy núi Yugandhara, có vòng dãy núi thứ hai có tên là\nIsadhara chìm sâu dưới đại dương 21.000 do tuần và nổi lên khỏi mặt nước\n21,000 do tuần.</p>\n<p>(3) Vòng núi thứ ba ở bên ngoài dãy núi Isadhara là dãy núi Karavikā,\nphần dưới của nó chìm sâu trong đại dương 10.500 do tuần và nổi lên khỏi\nmặt nước cao 10.500 do tuần.</p>\n<p>(4) Bên ngoài vòng thứ ba của dãy núi Karavīka, có dãy núi Sudassana\nmà phần dưới của nó chìm sâu trong đại dương 5.250 do tuần và nổi lên\nkhỏi mặt nước cao 5.250 do tuần.</p>\n<p>(5) Bên ngoài vòng núi Sudassana thứ tư, có vòng núi thứ năm gọi là\nNemindhara, phần dưới của nó chìm sâu dưới biển 2.625 do tuần và 2.625\ndo tuần nổi trên mặt nước.</p>\n<p>(6) Bên ngoài dãy núi Nemindhara thứ năm, có dãy núi thứ sáu gọi là\nVinataka, phần dưới của nó chìm xuống biển sâu 1.312 do tuần và 1.312 do\ntuần nổi trên mặt nước.</p>\n<p>(7) Bên ngoài dãy núi thứ sáu Vinataka có dãy núi thứ bảy tên gọi là\nAssakaṇṇa, phần dưới của nó chìm sâu dưới biển 656 do tuần và phần trên\nnổi trên mặt nước cao 656 do tuần. Giữa núi Sineru và giữa những dãy núi\ncó bảy vòng quanh là những con sông có tên gọi là Sīdā.</p>\n<p>Trong đại dương nằm về phía nam của núi Sineru có Nam Thiệm Bộ Châu,\ngọi là Diêm phù đề (Jambudīpa), nó được đặt tên theo cây Trâm mọc lên ở\nmặt trước của hải đảo, và hải đảo này được bao quanh bởi năm trăm tiểu\nđảo.</p>\n<p>Tương tự, trong đại dương nằm về phía tây của núi Sineru có Tây Ngưu\nXa Châu (Aparagoyāna); ở về phía bắc thì có Bắc Câu Lưu</p>\n<p>Châu (Uttarakuru); và ở hướng đông thì có Đông Thắng Thần Châu\n(Pubbavideha), mỗi châu đảo đều được bao quanh bởi năm trăm tiểu\nđảo.</p>\n<p>Ở Nam Thiệm Bộ Châu của xứ Jambudīpa, ngọn núi Himavantā cao năm trăm\ndo tuần và bề dài và bề rộng thì ba ngàn do tuần. Nó được làm cho hùng\nvĩ bởi tám mươi bốn ngàn đỉnh núi.</p>\n<p>Cây trâm mọc lên ở phía trước của châu Jambudīpa có ba chiều (dài,\nrộng và cao): đỉnh ngọn của nó bề rộng mười lăm do tuần; từ đất lên đến\nthân cây nơi mà các nhánh đâm ra, chiều cao của thân cây là 50 do tuần,\ncác nhánh cây lớn dài năm mươi do tuần, tàn cây rộng một trăm do tuần,\nchiều cao 100 do tuần.</p>\n<p>Sáu cây khổng lồ khác cũng có cùng kích thước, tồn tại cho đến khi\nkết thúc của thế giới: cây Hoa kèn trong cõi Assura tại chỗ cũ của chư\nthiên ở cõi Tam thập Tam thiên, ở dưới chân núi Sineru; cây Bông vải lụa\ntrong cõi của các vị Garuda ở Tây Ngưu Xa Châu; cây</p>\n<p>Như ý ở cõi Bắc Câu Lưu Châu; cây Ra mưa ở Đông Thắng Thần châu, và\ncây San-hô Ấn độ ở cõi Tam thập Tam thiên. Vòng dãy núi mà đánh dấu ranh\ngiới của vũ trụ có 82,000 do tuần chìm dưới đại dương và tám mươi hai\nngàn do tuần nổi lên trên mặt nước.</p>\n<p>Châu Diêm-phù-đề có hình thang (hình của phần trước của cỗ xe bò);\nTây Ngưu Xa Châu có hình chiếc gương bằng đồng thau (tức là hình tròn);\nĐông Thắng Thần Châu có hình lưỡi liềm; Bắc Câu Lưu Châu có hình vuông.\nDân cư của những châu ấy được xem là có những khuôn mặt mà hình thù thì\ngiống như hình thù của châu mà họ trú ngụ.</p>\n<p>Visuddhi-magga Mahāṭīkā, Volume I</p>\n<p>Trong mỗi hệ thống thế giới có (lâu đài của) mặt Trăng, đường kính là\nbốn mươi chín do tuần; (lâu đài của) mặt Trời, đường kính là năm mươi do\ntuần.</p>\n<p>Cõi Tam thập Tam thiên, cõi A-tu-la, cõi địa ngục vô gián\n(<em>avīci</em>), cõi Diêm-phù-đề (<em>Jambudīpa</em>) - Bốn cõi này,\nmỗi cõi rộng mười ngàn do tuần. Chúng được gọi là bốn cõi có bề rộng\nmười ngàn do tuần. Cõi Bắc Câu Lưu Châu rộng bảy ngàn do tuần; cõi Đông\nThắng Thần châu có kích thước tương tự; cõi Tây Ngưu Xa Châu rộng tám\nngàn do tuần. Tất cả những đặc điểm kể trên hình thành một hệ thống thế\ngiới. Những khoảng trống nơi mà ba hệ thống thế giới tiếp xúc nhau là\nnhững vùng trống vắng <em>Lokantarika</em>. Trong mỗi hệ thống thế giới\nthì ba cõi khổ là: cõi súc sanh, cõi ngạ quỉ và cõi A-tu-la\n(<em>asurakāya</em>), đều có chỗ trú ngụ của chúng ở trên quả đất, bên\ncạnh cõi người. Ở lớp dưới của quả đất có tám cõi địa ngục, cõi này ở\ndưới cõi kia, và mỗi đại địa ngục lại được bao quanh bởi những tiểu địa\nngục có sự đau khổ liên tục được gọi là <em>ussada niraya</em>. Những\ncõi <em>niraya</em>, súc sanh, ngạ quỉ và <em>asurakāya</em> được gọi là\nbốn khổ thú (<em>apaya</em>).</p>\n<p>Cõi người nằm trên quả đất. Cõi Tứ thiên vương nằm trên đỉnh núi\nYugandhara, ở một nửa chiều cao của núi Sineru. Chư thiên cõi Tam thập\nTam thiên trú ngụ trên đỉnh núi Sineru. Do đó hai cõi chư thiên này\nthuộc quả đất. Bên trên của cõi Tam thập Tam thiên là cõi Dạ-ma\n(<em>yāmā</em>); trên nữa là cõi Đâu suất đà (<em>Tusitā</em>); trên nữa\nlà cõi Hoá lạc thiên (<em>Nimmānarati</em>); và trên nữa là cõi Tha hoá\ntự tại thiên (<em>Paranimmita-vasavatti</em>). Sáu cõi chư thiên này\ncùng với cõi người được gọi là bảy cõi Dục giới hạnh phúc (<em>Kamā\nsugati bhūmi</em>). Bảy cõi hạnh phúc này và bốn cõi khổ được gọi chung\nlà những cõi Dục giới (<em>Kamā bhūmi</em>).</p>\n<p>Sáu cõi chư thiên kể trên thuộc về Dục giới, có ba cõi Phạm thiên gồm\nPhạm chúng thiên (<em>Brahmapārisajjā</em>), Phạm phụ thiên\n(<em>Brahmapurohitā)</em> và Đại phạm thiên (<em>Mahābrahmā</em>) là ba\ncõi Phạm thiên liên quan đến sơ thiền Sắc giới (<em>Rūpā-vacara</em>).\nHọ ở chung một cõi.</p>\n<p>Bên trên ba cõi Phạm thiên thuộc sơ thiền Sắc giới, có ba cõi Phạm\nthiên thuộc nhị thiền Sắc giới ở trong cùng một cõi, đó là Thiểu quang\nthiên (<em>Parittābhā</em>), Vô lượng quang thiên (<em>Appamānābhā</em>)\nvà Quang âm thiên (<em>Abhassarā</em>).</p>\n<p>Bên trên ba cõi Phạm thiên thuộc nhị thiền Sắc giới, có ba cõi Phạm\nthiên thuộc tam thiền trong cùng một cõi chung, đó là: Thiểu tịnh thiên\n(<em>Parittasubhā</em>), Vô lượng tịnh thiên (<em>Appamāṇāsubha</em>) và\nBiến tịnh thiên (<em>Subbhakiṇṇā</em>).</p>\n<p>Bên trên những cõi này có hai cõi Phạm thiên (cũng thuộc về Sắc giới)\ntrong cùng một tầng thiền, đó là: cõi Quảng quả (<em>Vehapphala</em>) và\ncõi của chúng sanh vô tưởng (<em>Asaññasatta</em>). Bên trên hai cõi này\nlà cõi Vô phiền (<em>Avihā</em>), Vô nhiệt (<em>Atappā</em>), Thiện kiến\n(<em>Sudassā</em>), Thiện hiện (<em>Sudassī</em>) và Sắc cứu cánh\n(<em>Akaniṭṭha</em>) – là năm cõi Tịnh cư này liên quan đến tứ thiền Sắc\ngiới. Như vậy có cả thảy mười sáu cõi Phạm thiên hữu sắc.</p>\n<p>Trên mười sáu cõi Phạm thiên hữu sắc, có bốn cõi Phạm thiên thuộc Vô\nsắc giới, đó là Hư không vô biên xứ (<em>Ākāsānañcā-yatana</em>), Thức\nvô biên xứ (<em>Viññāṇañcā-yatana</em>), Vô sở hữu xứ\n(<em>Ākiñcaññā-</em> <em>yatana</em>) và Phi tưởng phi phi tưởng xứ\n(<em>Nevasaññāvāsaññā-yatana</em>), cõi này nối tiếp nằm trên cõi\nkia.</p>\n<p>Như vậy có mười sáu cõi Phạm thiên hữu sắc và bốn cõi Phạm thiên vô\nsắc, cả thảy là hai mươi cõi Phạm thiên. Khi mười một cõi Dục giới được\nthêm vào, thì có ba mươi mốt cõi trong một hệ thống thế giới. Đây là bài\nmô tả tóm tắt về các cõi.</p>\n<p>Theo cách đã nói ở trên, Đức Phật có sự hiểu biết hoàn toàn về những\nthế giới vô biên làm chỗ nương tựa cho đời sống của chúng sanh. Sự hiểu\nbiết hoàn toàn và rõ ràng về thế giới hữu tình, thế giới hữu vi và thế\ngiới vô tình là ân đức Lokavidū. Năm uẩn của Đức Phật là người sở hữu ân\nđức ấy.</p>"}, {"n": 6, "pali": "Anuttaro purisadammasārathi", "paliUp": "ANUTTARO PURISA DAMMASĀRATHI", "vi": "Vô Thượng Sĩ · Điều Ngự Trượng Phu", "short": "<p>Bởi vì Ngài là bậc vô song trong việc điều phục những kẻ đáng\nđược điều phục.</p>", "detail": "<p><em>Visuddhi-magga</em> có hai nghĩa về chữ\n<em>Anuttaropurisadammasārathi</em>: <em>anuttaro</em> (Vô thượng sĩ) là\nmột ân đức và <em>dammasārathi</em> là một ân đức khác. Và nó cũng có\nmột sự diễn dịch khác là định nghĩa hai ân đức thành một.</p>\n<p><strong><em>(a). Anuttaro</em></strong>: Đức Phật vô song về giới,\nv.v… trong tất cả thế gian đến nỗi Ngài giữ địa vị tối cao về ân đức này\ntrong thế giới hữu tình.</p>\n<p>Giải rộng : Đức Phật tối thắng về giới, về định, về tuệ, về giải\nthoát,và về trí tuệ dẫn đến giải thoát (giải thoát tri kiến). Sự tối cao\nnày là ân đức <em>anuttaro</em>; năm uẩn của Đức Phật là người sở hữu ân\nđức ấy.</p>\n<p>(b) <strong><em>Purisadammasārathi</em></strong>: ” Bậc điều phục\nnhững kẻ đáng được điều phục.” (<em>purisadamma,</em> những kẻ đáng được\nđiều phục; <em>sārathi</em>, người điều phục, tức là ông thầy lão luyện\nhay người huấn luyện). Những người xứng đáng được điều phục gồm có nhân\nloại, chư thiên và Phạm thiên. Ví dụ: Đức Phật đã thâu phục rồng chúa\nApalāla, rồng chúa Cūḷodara, rồng chúa Mahodara, rồng chúa Aggisikha,\nrồng chúa Dhūmasikha, rồng chúa Aravāḷa, voi chúa Dhanapāla, v.v… và làm\ncho họ xa lìa hành vi tàn bạo và quy y Tam bảo. Rồi Đức Phật thuần hoá\ndu sĩ Saccaka, con trai của Nigaṇṭha; chàng trai trẻ Ambaṭṭha; những vị\nBà-la-môn Pokkharasāti, Soṇadanta và Kūṭadanta, v.v...</p>\n<p>Ngài cũng điều phục chư thiên hùng mạnh như Āḷavaka, Sūciloma,\nKharaloma và ngay cả Sakka, vua của chư thiên.</p>\n<p>Đức Phật không chỉ thuần phục các chúng sanh thoát khỏi giai đọan\nhoang dã (<em>savage</em>) của họ để trở thành những đệ tử của Ngài, mà\ncòn nâng cao cho những người có giới đức, có sự thanh tịnh của giới để\nchứng đắc sơ thiền, hay các bậc thánh là những vị thánh Nhập lưu, để\nchứng đắc ba bậc cao bằng cách chỉ cho họ phương pháp tu tập.</p>\n<p>Bởi vậy ‘sự thuần phục’ của Ngài cũng bao gồm sự dẫn dắt những người\nđã được thuần phục một nửa trước rồi đến đạo quả A-la-hán. Do đó,\n<em>Purisadammasārathi</em> nghĩa là làm cho những chúng sanh chưa thuần\nhoá được an trú trong giới bậc thấp, và dẫn dắt những người có giới bậc\nthấp ấy (tức là đã được thuần phục một nửa) đạt được những lợi ích bậc\ncao dẫn đến A-la-hán quả (<em>arahatta-phala)</em>. Trí tuệ giáo hóa kẻ\nkhác như vậy là ân đức <em>dammasārathi</em>. Năm uẩn của Đức Phật là\nngười sở hữu ân đức ấy.</p>\n<p>Trong sự diễn dịch tổng hợp của chữ <em>anuttaro</em> và\n<em>purisadammasārathi</em>, chỉ một ân đức được kể ra, nghĩa là\n“<em>Đức Phật</em> <em>là bậc vô song trong việc thuần phục những kẻ\nchưa được thuần hoá.</em>”</p>\n<p>Giải thích điều này: một người huấn luyện ngựa, khi huấn luyện một\ncon ngựa, người ấy không thể huấn luyện nó cho thuần thục trong một ngày\nđược. Ông ta phải huấn luyện nó trải qua nhiều ngày lập đi lập lại.\n(Huấn luyện những con vật khác như voi, bò, v.v… cũng giống như vậy).\nNgay cả khi con ngựa được cho là được thuần hoá nhưng nó vẫn không thoát\nkhỏi những sự tinh nghịch (những con vật khác cũng như vậy). Nhưng Đức\nPhật có thể thuần phục một người chỉ trong một lần (tức là trong một lần\nthuyết giảng giáo pháp) để chứng đắc tám <em>vimokkha-jhāna</em> (giải\nthoát định) hay chứng đắc A-la-hán quả (<em>arahatta-phala)</em>. Khi\nngười đệ tử đã chứng đắc A-la-hán quả, vị ấy trở nên hoàn toàn được\nthuần hoá không bao giờ tỏ ra bất cứ sự đùa cợt nào nữa. Trí tuệ điều\nphục những kẻ chưa được điều phục (tức là còn vô minh) là ân đức\n<em>ấy</em></p>"}, {"n": 7, "pali": "Satthā devamanussānaṁ", "paliUp": "SATTHĀDEVA MANUSSĀNAṂ", "vi": "Thiên Nhân Sư", "short": "<p>Bởi vì Ngài là Thầy của chư thiên và nhân loại, chỉ cho họ con\nđường dẫn đến Niết bàn.</p>", "detail": "<p>Chữ này có nghĩa là Đức Phật là bậc hướng dẫn, chỉ dạy cho chư thiên\nvà nhân loại để đạt được cho chính họ những lợi ích trong hiện tại,\nnhững lợi ích trong tương lai, và lợi ích tối thượng là Niết bàn.</p>\n<p>Điều này quả thật đúng như vậy. Đức Phật giảng dạy, sách tấn cho tất\ncả chúng sanh để thành đạt lợi ích trong hiện tại dành cho một số chúng\nsanh, thành đạt những lợi ích trong những kiếp tương lai dành cho số\nchúng sanh khác, và giúp chứng đắc lợi ích tối thượng là Niết bàn dành\ncho những chúng sanh khác, mỗi chúng sanh tùy thuộc vào sự đầy đủ về\nphước quá khứ của người ấy. Do đó, trí tuệ trong việc giúp đỡ chư thiên\nvà nhân loại đạt được những lợi ích hiện tại, những lợi ích tương lai,\nvà lợi ích Niết bàn là ân đức <em>satthādevamanussānaṃ</em>. Năm uẩn của\nĐức Phật là người sở hữu ân đức ấy.</p>\n<p>Một cách giải thích khác: Đức Phật giống như người chủ của đoàn\nthương buôn, cho nên Ngài được gọi là\n<em>Satthādeva-manussānaṃ</em>.</p>\n<p>Giải rộng:</p>\n<p>Một người lãnh đạo có trí tuệ của đoàn thương buôn hướng dẫn đoàn\nthương buôn an toàn vượt qua chặng đường đầy nguy hiểm và gian nan. Có\nnăm loại chặng đường đầy nguy hiểm và gian nan, đó là</p>\n<ol type=\"i\">\n<li><p>chặng đường khét tiếng là có những tên cướp đường;</p></li>\n<li><p>chặng đường đi qua vùng đất hoang có thú dữ như sư tử hay cọp đi\nlại;</p></li>\n<li><p>dãi đất trơ trọi không có vật thực;</p></li>\n<li><p>chặng đường đi qua vùng đất khô cháy không có nước;</p></li>\n<li><p>chặng đường đi qua vùng đất có dạ-xoa lộng hành quấy\nphá.</p></li>\n</ol>\n<blockquote>\n<p>Cũng như một người lãnh đạo giỏi của đoàn thương buôn hướng dẫn đoàn\nthương buôn vượt qua năm loại chặng đường đầy hiểm nguy. Cũng vậy Đức\nPhật bảo vệ những người đi trong con đường sanh tử thoát khỏi những hiểm\nnguy của sanh, già, bịnh và chết, sầu, bi, khổ, ưu, não, tham, sân, si,\nmạn, kiến và những hành động bất thiện, và hướng dẫn họ đi đến chỗ an\ntoàn của Niết bàn.</p>\n<p>Do đó giáo pháp của Đức Phật mà đưa chúng sanh đến Niết bàn là ân đức\nThiên nhân sư (<em>satthādeva-manussānaṃ</em>). Năm uẩn của Đức Phật là\nngười sở hữu ân đức ấy.</p>\n<p>(Ân đức <em>satthādeva-manussānaṃ</em> không nên xem là chỉ bao gồm\nchư thiên và nhân loại không thôi. Chữ <em>devamanussānaṃ</em> được dùng\nưu tiên cho những chúng sanh có những kiếp sống may mắn hạnh phúc và đủ\nduyên để được giải thoát. Tuy nhiên, Đức Phật cũng cho lời giáo giới\nthích hợp đến các loài súc sanh để chúng cũng được lợi ích từ lời khuyên\nấy và nhờ đó có đủ túc duyên để chứng đắc đạo quả trong kiếp sống kế\ntiếp hoặc trong kiếp thứ ba. Bộ Chú giải có nêu ra ví dụ về Maṇḍūka\nDevaputta, sẽ được kể ra dưới đây.)</p>\n</blockquote>"}, {"n": 8, "pali": "Buddho", "paliUp": "BUDDHA", "vi": "Phật", "short": "<p>Bởi vì Ngài là bậc Giác ngộ, biết và giảng dạy Tứ Thánh\nĐế.</p>", "detail": "<p>Ngài được gọi là Phật (<em>Buddha</em>) bởi vì Ngài biết đầy đủ tất\ncả những pháp cần biết. Trong một ý nghĩa khác, Ngài là người giác ngộ\nTứ thánh đế và đem ra giáo hoá chúng sanh cùng giác ngộ. Cho nên Ngài\nđược gọi là Phật (<em>Buddha</em>). Giữa ân đức thứ hai, ân đức Chánh\nbiến tri (<em>sammāsambuddha</em>) và ân đức thứ tám là Phật\n(<em>Buddha</em>), sự khác biệt nằm ở chỗ ân đức Chánh biến tri chỉ về\nTứ Diệu Đế trong khi ân Đức Phật chỉ về Nhất thiết trí\n(<em>Sabbaññuta-ñāṇa</em>). Tuy nhiên, nếu ân đức <em>Buddho</em> được\nxem là trí tuệ tối cao giống như trí tuệ tối cao -\n<em>Sammāsambuddho</em>, thì ân đức Chánh biến tri liên quan đến phương\ndiện Thông đạt (<em>Paṭivedha</em> <em>ñāṇa</em>) trong trí tuệ của Đức\nPhật, trong khi ân Đức Phật liên quan đến phương diện thiện xảo thuyết\ngiảng (<em>Desanā ñāṇa</em>) trong việc khai</p>\n<p>ngộ cho chúng sanh khác trong trí tuệ của Đức Phật.</p>"}, {"n": 9, "pali": "Bhagavā", "paliUp": "BHAGAVĀ", "vi": "Thế Tôn", "short": "<p>Bởi vì Ngài có sáu đức tánh cao quý, đó là tự tại (issariya), trí\nthuộc về 9 pháp Siêu thế, tức là Đạo Quả và Niết bàn\n(magga-phalanibbāna), danh tiếng và đồ chúng (yasa), sự lộng lẫy trong\nsự toàn hảo về thân (sirī), khả năng thành tựu (kāmma), và sự tinh cần\n(payatta)</p>", "detail": "<p>Ân đức này của Đức Phật được giải thích bằng nhiều cách trong bộ Đại\nnghĩa thích (<em>Mahā Niddesa Pāḷi</em>). Bộ Chú giải cũng giải thích ân\nđức này bằng sáu cách, trong khi bộ <em>Visuddhimagga</em>\n<em>Mahāṭīkā</em> nêu ra bảy cách diễn dịch khác nhau. Ở đây chúng tôi\nsẽ bàn về phương pháp giải thích thứ nhất trong Pāḷi mà cũng là phương\npháp giải thích thứ ba trong bộ Chú giải. Đây là ý nghĩa chung được nêu\nra bởi các dịch giả Miến điện trong bản dịch sát nghĩa của từ, tức là\n“<em>Người</em> <em>có sáu pháp cao quý</em>” (<em>Bhaga</em>, sáu đức\ntánh cao quý; <em>vant,</em> sở hữu). Đức Phật được gọi là\n<em>Bhagavā</em> bởi vì Ngài có sáu đức tánh cao quý (mà các Thinh văn\nđệ tử không thể đạt được), đó là:</p>\n<p>(i) <em>Issariya</em> (ii) <em>Dhamma</em> (iii) <em>Yas</em>a (iv)\nSirī (v) <em>Kāmma</em> (vi) <em>Payatta</em>.</p>\n<p><strong>(i) Issariya - Tự tại.</strong></p>\n<p>Nó có nghĩa là khả năng vốn có của Đức Phật khiến các pháp đi theo ý\nmình. <em>Issariya</em> có hai loại: <em>lokuttarācittissariya</em> (tự\ntại thuộc siêu thế gian) và <em>lokīcittissariya</em> (tự tại thuộc thế\ngian).</p>\n<p>Về sự tự tại siêu thế gian, Đức Phật có khả năng ý chí không ai sánh\nbằng. Trong việc thị hiện Song thông, để làm cho một dòng nước tuôn ra\ntừ trên thân như ý muốn, Ngài nhập vào Chuẩn bị định của đề mục\n<em>āpo-kasiṇa</em> và rồi lập nguyện, “Hãy phát ra một dòng nước” là\nmột lộ trình tâm riêng biệt (<em>adhiṭṭhāṇa-vīthi</em>). Rồi Ngài lại\nnhập vào Chuẩn bị định của để mục nước <em>āpo-kasina</em> lần nữa. Rồi\nlộ trình thần thông (<em>abhiññāṇa-vīthi</em>) sanh lên khiến cho dòng\nnước xuất hiện từ bất cứ chỗ nào trên thân của Ngài theo như ý muốn.</p>\n<p>Như vậy, để có một dòng nước tuôn ra từ chỗ mong muốn trên thân của\nNgài, Đức Phật đã phải trải qua bốn lộ trình tâm khác nhau.</p>\n<p>Cũng vậy, để có một luồng lửa tuôn ra từ chỗ mong muốn trên thân, Đức\nPhật nhập vào Chuẩn bị định đề mục lửa (<em>tejo-kasiṇa</em>) rồi nguyện\nrằng, ” Hãy phát ra một luồng lửa” là một lộ trình tâm riêng biệt. Rồi\nNgài lại nhập vào Chuẩn bị định của đề mục lửa lần nữa. Rồi lộ trình\nthần thông sanh lên khiến cho luồng lửa xuất hiện từ bất cứ chỗ nào</p>\n<p>trên thân của Ngài theo như ý muốn.</p>\n<p>Nói tóm lại, để có được một tia nước tuôn ra từ thân, Đức Phật phải\ntrải qua bốn lộ trình tâm riêng biệt. Để có được một luồng lửa tuôn ra\ntừ thân cũng cần phải có những điều kiện như vậy. Sự tự tại trong năng\nlực tâm của Đức Phật là trong việc trải qua lộ trình tâm khi nhập vào\nChuẩn bị định, Ngài có thể khiến lộ trình tâm dừng lại với số lượng bao\nnhiêu sát na tâm do Ngài chọn. Những sát na tâm hộ kiếp (<em>bhavaṅga\ncitta</em>) mà phải can thiệp vào các lộ trình tâm riêng biệt cũng bị\ngiới hạn trong 2 sát na tâm. (So sánh điều này với trường hợp của các vị\nthánh đệ tử thì các ngài cần nhiều sát na tâm hộ kiếp mà các ngài cảm\nthấy cần thiết). Sự tự tại trong việc sắp xếp các lộ trình tâm riêng\nbiệt và những sát na tâm hộ kiếp như ý muốn là những điểm đặc sắc trong\nsự thành tựu về năng lực tâm của Đức Phật. Đây là khả năng kiểm soát sự\nđịnh tâm trong thiền hợp thế.</p>\n<p>Cũng vậy, trong tâm siêu thế về <em>arahatta-phala</em>, Đức Phật có\nnăng lực tâm mà không ai sánh bằng. Do khả năng này, Ngài nhập vào\nA-la-hán quả định trong một ít sát na tâm khi Ngài dừng nghỉ giữa một\nđiểm thời gian đặc biệt nào đó trong thời thuyết giảng của Ngài</p>\n<p>và thời pháp còn lại, trong thời gian ngắn ngủi này thính chúng nói\nlời “Sādhu!” (” Lành thay!“). Sự thật thì Đức Phật thường nhập vào\nA-lahán quả định trong những giây phút nhàn rỗi rất ngắn ngủi (hãy xem\nbộ <em>Aṭṭhasalinī Mūlaṭīkā</em>). Đây là cách mà Đức Phật có sự kiểm\nsoát kỳdiệu về năng lực tâm của Ngài trong tâm siêu thế.</p>\n<p><strong>Bài tóm tắt về những ân đức của Đức Phật</strong></p>\n<p>Tất cả những ân đức chói sáng của Đức Phật có thể được sắp xếp thành\nhai loại:</p>\n<p>(1) Những ân đức nói về sự thành tựu của Đức Phật dành cho chính bản\nthân Ngài (<em>attahita sampatti</em>)</p>\n<p>(2) Những ân đức về sự phục vụ của Đức Phật để đem lại hạnh phúc\nchung cho chúng</p>\n<p>sanh (<em>parahita paṭipatti</em>).</p>\n<p>Trong hạng loại thứ nhất có hai khía cạnh, (i) sự thành công mà Đức\nPhật đạt được trong việc đọan trừ các khuynh hướng tạo ra phiền não, và\n(ii) sự đạt được nhiều loại Trí tuệ (những khả năng bẩm sinh của Đức\nPhật xuất phát từ hai nguồn này).</p>\n<p>Trong hạng loại thứ hai về những ân đức của Đức Phật cũng vậy, có hai\nkhía cạnh: (i) sự nỗ lực cao tột trong việc thuyết pháp đến chúng sanh\nhoàn toàn xuất phát từ lòng bi mẫn, không bị vấy nhiễm chút nào về sự\nmong cầu lợi lộc hay danh vọng; và (ii) sự nhẫn nại vô biên trong việc\nmong cầu hạnh phúc ngay cả đến những người chống nghịch với Ngài và cũng\nnhẫn nại chờ đợi thời gian chín muồi của những người nghe để có thể giác\nngộ chân lý. Đức Phật thọ lãnh những vật cúng dường thuộc tứ sự là một\nhình thức đem lại lợi ích cho các thí chủ khiến họ gieo tạo được phước\nbáu to lớn. Như vậy, chín ân đức như Arahaṃ được giảng dạy để nói rõ hai\nphương diện ở trên về những sự thành tựu của chính Ngài và sự phục vụ\ncủa Ngài để đem lại hạnh phúc cho chúng sanh. Chín ân đức được đọc thành\nhai khía cạnh theo cách sau đây:</p>\n<p><strong><em>Arahaṃ</em></strong> mô tả rõ ràng sự thành công của Đức\nPhật trong việc đọan diệt tất cả phiền não.</p>\n<p><strong><em>Sammāsambuddha</em></strong> và\n<strong><em>Lokavidū</em></strong> mô tả rõ ràng sự sở hữu nhiều dạng\ntrí tuệ của Đức Phật. (Ở đây có thể nêu ra câu hỏi, “Phải chăng ân đức\n<em>Lokavidū</em> cũng đại diện cho ân đức Chánh biến tri?” Câu trả lời\nlà “Vâng, đúng như vậy.” Tuy nhiên, có sự khác biệt này:</p>\n<p><strong><em>Sammāsambuddho</em></strong> đại diện cho tánh có hiệu\nquả của ân đức <em>Chánh biến tri</em>, trong khi <em>Lokavidū</em> nói\nvề hiệu quả của trí phân tích của Đức Phật về dòng tâm của người nghe,\nnhư khuynh hướng, v.v... Vì vậy mà hai ân đức khác nhau này được nêu\nra).</p>\n<p><strong><em>Vijjācaraṇa sampanno</em></strong> mô tả đầy đủ sự thành\ntựu toàn diện của Đức Phật dành cho chính Ngài.</p>\n<p><strong><em>Sugata</em></strong> nói rõ cả về sự thành tựu của Đức\nPhật dành cho chính Ngài và sự thành đạt trong việc làm lợi ích cho\nchúng sanh, cùng với nguyên nhân cơ bản của cả hai.</p>\n<p><strong><em>Anuttaropurisadammasārathi</em></strong> và\n<strong><em>Satthādevamanussāna</em></strong> chỉ rõ về sự thành đạt của\nĐức Phật trong việc đem lại lợi lạc cho chúng sanh.</p>\n<p><strong><em>Buddho</em></strong> nói lên sự thành tựu đối với bản\nthân cũng như sự thành tựu trong việc đem lại lợi ích cho chúng sanh.\n(Sau khi nêu ra danh hiệu</p>\n<p><strong><em>Sammāsamuddho</em>,</strong> Đức Phật dạy thêm về\n<em>Buddho</em> vì ân đức trước chỉ về trí tuệ thông đạt trong khi ân\nđức sau mang ý nghĩa về trí tuệ giáo hoá.</p>\n<p><strong><em>Bhagavā</em></strong> làm sáng tỏ cả sự thành tựu của Đức\nPhật dành cho chính Ngài và sự thành công trong việc đem lại lợi ích cho\nchúng sanh.</p>\n<p>Xét theo một khía cạnh khác thì những ân đức cao quý của Đức Phật\nđược phân thành ba loại, đó là: (i) Những ân đức là nguyên nhân\n(<em>hetu</em>), (ii) Những ân đức là kết quả (<em>phala</em>) và (iii)\nNhững ân đức đemlại lợi ích cho kẻ khác (<em>sattū pakāra</em>). (Ba\nloại ân đức này có thể được gọi là sự thành công về nhân, sự thành công\nvề quả, và sự thành công về lợi lạc của thế gian.)</p>\n<p>Bốn ân đức đầu tiên – <em>Arahaṁ, Sammāsambuddho</em>,\n<em>Vijjācaraṇasampanno, Lokavidū</em>, mô tả những nguyên nhân của các\nân đức mà Đức Phật có được.</p>\n<p><em>Anuttaropurisadammasārathi</em> và <em>Sattādevamanussānaṁ</em>\nmô tả rõ ràng sự thành công của Đức Phật trong việc đem lại lợi ích cho\nchúng sanh.</p>\n<p><em>Buddho</em> chỉ rõ sự thành công của Đức Phật về nguyên nhân hạnh\nphúc cũng như sự thành tựu trong việc đem lại lợi ích cho chúng\nsanh.</p>\n<p><em>Sugata</em> và <em>Bhagavā</em> mô tả cả ba loại thành tựu, đó là\nvề nguyên nhân, về kết quả và về hạnh phúc của thế gian. (<em>Hai cách\ngiải thích này được trích ra từ bộ Visuddhi-magga</em></p>\n<p><em>Mahāṭīkā, cuốn I)</em></p>"}]}, "phap": {"title": "Ân Đức Pháp", "pali": "Dhammaguṇa · 6 ân đức", "kinh": "<b>Svākkhāto</b> bhagavatā dhammo, <b>sandiṭṭhiko akāliko ehipassiko opaneyyiko paccattaṁ veditabbo viññūhī</b>ti.", "items": [{"n": 1, "pali": "Svākkhāto bhagavatā dhammo", "paliUp": "SVĀKKHĀTO", "vi": "Pháp được Đức Thế Tôn khéo thuyết giảng", "short": "<p>Giáo pháp được Đức Thế Tôn thuyết giảng một cách hoàn hảo: toàn hảo ở phần đầu, phần giữa và phần cuối, đầy đủ cả văn lẫn nghĩa, không sai lệch dù chỉ một điểm.</p>", "detail": "<p><b>Svākkhāta</b> = <i>su</i> (khéo, tốt đẹp) + <i>akkhāta</i> (được thuyết giảng). Ân đức này bao trùm cả <b>Pháp học</b> (pariyatti) lẫn <b>chín pháp Siêu thế</b> (4 Đạo, 4 Quả, Níp-bàn).</p><p>Về Pháp học: giáo pháp <i>toàn hảo phần đầu</i> (giới), <i>toàn hảo phần giữa</i> (định), <i>toàn hảo phần cuối</i> (tuệ), có đầy đủ văn (byañjana) và nghĩa (attha), tuyên bố đời sống phạm hạnh hoàn toàn thanh tịnh. Không một lời nào của Đức Phật là vô ích hoặc mâu thuẫn với lời khác.</p><p>Về Pháp Siêu thế: được gọi là khéo thuyết vì đường lối thực hành (paṭipadā) được trình bày <i>đúng như thật</i> — không rơi vào cực đoan lợi dưỡng hay khổ hạnh, chính là Trung đạo; và Níp-bàn được trình bày đúng theo tự tánh tịch tịnh của nó.</p><p><i>Nguồn: Visuddhimagga VII — Dhammānussati.</i></p>"}, {"n": 2, "pali": "Sandiṭṭhiko", "paliUp": "SANDIṬṬHIKO", "vi": "Pháp thiết thực hiện tại, tự mình thấy rõ", "short": "<p>Người thực hành tự mình chứng nghiệm và thấy rõ kết quả ngay trong hiện tại bằng trí tuệ của chính mình, không phải nhờ tin theo người khác.</p>", "detail": "<p><b>Sandiṭṭhika</b> = pháp mà bậc Thánh <i>tự mình thấy</i> (sāmaṁ diṭṭha) bằng Đạo trí và Quả trí, không cần dựa vào lòng tin nơi kẻ khác. Vị chứng Đạo Quả tự biết rõ phiền não nào đã đoạn, còn phiền não nào chưa đoạn, như người uống nước tự biết nóng lạnh.</p><p>Cách giải thích thứ hai: <i>diṭṭha</i> cũng có nghĩa là “chinh phục”. Pháp này chinh phục được vòng luân hồi ngay nơi người thực hành, cho kết quả <b>tức thời trong hiện tại</b> chứ không phải chờ đến kiếp sau — như tham vừa dứt thì sự thiêu đốt của tham cũng dứt ngay lúc ấy.</p>"}, {"n": 3, "pali": "Akāliko", "paliUp": "AKĀLIKO", "vi": "Pháp cho quả không chờ thời gian", "short": "<p>Thánh Đạo vừa sanh thì Thánh Quả trổ ngay liền kề, không có khoảng cách thời gian, không phải đợi ngày giờ hay kiếp sau.</p>", "detail": "<p><b>Akālika</b> = không (a) + thuộc thời gian (kālika). Nghiệp thiện hiệp thế cho quả phải chờ thời — có nghiệp cho quả kiếp này, có nghiệp cho quả kiếp sau, kiếp sau nữa. Riêng <b>Thánh Đạo</b> thì khác: ngay sát-na tâm kế tiếp sau Đạo tâm là Quả tâm sanh khởi, không hề gián đoạn.</p><p>Vì vậy ân đức này chỉ nói riêng về chín pháp Siêu thế, đặc biệt là bốn Thánh Đạo. Đây là điểm phân biệt rõ giữa quả của thiện hiệp thế và quả của Đạo Siêu thế.</p>"}, {"n": 4, "pali": "Ehipassiko", "paliUp": "EHIPASSIKO", "vi": "Pháp đáng được mời đến để thấy", "short": "<p>Pháp có thật, trong sạch và hiển nhiên, nên xứng đáng nói lời mời: “Hãy đến mà xem!” — không có gì phải che giấu.</p>", "detail": "<p><b>Ehipassika</b> = xứng đáng với lời mời <i>ehi passa</i> (“hãy đến mà nhìn xem”). Chỉ vật gì <b>thật sự có mặt</b> và <b>hoàn toàn trong sạch</b> mới đáng mời người khác đến xem. Chín pháp Siêu thế có thật theo nghĩa chân đế, và thanh tịnh tuyệt đối như vầng trăng giữa hư không quang đãng.</p><p>Người ta không thể mời ai đến xem thứ không có thật, cũng không mời đến xem thứ dơ bẩn. Vì Pháp vừa thật vừa tịnh nên Đức Phật luôn mở lời mời chúng sanh đến kiểm chứng — đây là ân đức làm nên tính <i>khả nghiệm</i> của Phật Pháp.</p>"}, {"n": 5, "pali": "Opaneyyiko", "paliUp": "OPANEYYIKO", "vi": "Pháp đáng được đưa vào thân tâm để thực hành", "short": "<p>Pháp xứng đáng để hành giả đưa vào trong tự thân mà tu tập, dẫn dắt đến Níp-bàn — dù y áo đang cháy trên đầu cũng nên gác lại để hành Pháp trước.</p>", "detail": "<p><b>Opaneyyika</b> = đáng được <i>upanaya</i> — đưa đến, hướng vào. Có hai nghĩa:</p><p>(a) Pháp Siêu thế đáng được đưa vào tâm mình bằng sự tu tập, dù phải hy sinh cả thân mạng. Chú giải ví: ngay cả khi y phục hay đầu tóc đang bốc cháy, hành giả vẫn nên tạm bỏ đó mà tu tập Thánh Đạo trước, vì việc dập lửa chỉ cứu một kiếp còn Thánh Đạo cứu vô lượng kiếp.</p><p>(b) Bốn Thánh Đạo <i>đưa hành giả đến</i> Níp-bàn, còn Quả và Níp-bàn thì đáng được hướng tâm đến bằng sự chứng đạt.</p>"}, {"n": 6, "pali": "Paccattaṁ veditabbo viññūhi", "paliUp": "PACCATTAṀ VEDITABBO VIÑÑŪHI", "vi": "Pháp mà bậc trí tự mình chứng biết", "short": "<p>Mỗi bậc trí tự mình chứng nghiệm Pháp trong tâm mình; thầy không thể chứng thay trò, và sự chứng đạt của người này không thể chuyển cho người kia.</p>", "detail": "<p><b>Paccattaṁ</b> (riêng từng người) <b>veditabbo</b> (đáng được biết) <b>viññūhi</b> (bởi bậc trí). Pháp Siêu thế chỉ có thể được kinh nghiệm <i>bên trong dòng tâm của chính hành giả</i>.</p><p>Chú giải nêu ví dụ: thầy tu tập thì trò không do đó mà dứt phiền não; trò chứng Đạo thì thầy cũng không nhờ đó mà an trú Quả. Cũng như người này ăn thì người kia không no. Sự chứng ngộ hoàn toàn mang tính cá nhân, không thể vay mượn, không thể trao truyền.</p><p><i>Viññū</i> ở đây chỉ bậc có trí tuệ đủ chín muồi — hạng phàm phu chưa tu tập không thể tự biết được Pháp này.</p>"}]}, "tang": {"title": "Ân Đức Tăng", "pali": "Saṅghaguṇa · 9 ân đức", "kinh": "<b>Supaṭipanno</b> bhagavato sāvakasaṅgho, <b>ujupaṭipanno</b> bhagavato sāvakasaṅgho, <b>ñāyapaṭipanno</b> bhagavato sāvakasaṅgho, <b>sāmīcipaṭipanno</b> bhagavato sāvakasaṅgho … <b>āhuneyyo pāhuneyyo dakkhiṇeyyo añjalikaraṇīyo anuttaraṁ puññakkhettaṁ lokassā</b>ti.", "items": [{"n": 1, "pali": "Supaṭipanno", "paliUp": "SUPAṬIPANNO", "vi": "Khéo thực hành", "group": "hanh", "short": "<p>Chư Thánh đệ tử Tăng thực hành tốt đẹp, đúng theo lời dạy của Đức Thế Tôn, đi trên con đường Trung đạo không thối chuyển.</p>", "detail": "<p><b>Su</b> (tốt đẹp) + <b>paṭipanna</b> (đã thực hành). Chư Tăng thực hành đúng theo pháp đã được khéo thuyết (svākkhāta-dhamma), thọ trì lời giáo huấn của bậc Đạo Sư một cách chân chánh, không đi lệch sang con đường lợi dưỡng hay khổ hạnh ép xác.</p><p>“Khéo thực hành” cũng có nghĩa là <i>không quay lui</i>: đã bước vào Thánh Đạo thì không còn thối chuyển trở lại phàm địa.</p>"}, {"n": 2, "pali": "Ujupaṭipanno", "paliUp": "UJUPAṬIPANNO", "vi": "Thực hành chân trực", "group": "hanh", "short": "<p>Thực hành ngay thẳng, không quanh co bằng thân, khẩu, ý — tránh xa cả hai cực đoan, đi đúng con đường Trung đạo.</p>", "detail": "<p><b>Uju</b> = ngay thẳng, không cong vạy. Chư Tăng thực hành đường lối chân trực: không giả dối nơi thân nghiệp, khẩu nghiệp và ý nghiệp; không có sự lừa phỉnh (māyā) hay xảo trá (sāṭheyya).</p><p>Chân trực còn có nghĩa đi thẳng đến Níp-bàn theo Trung đạo, tránh cực đoan hưởng thụ dục lạc (kāmasukhallikānuyoga) và cực đoan hành xác (attakilamathānuyoga).</p>"}, {"n": 3, "pali": "Ñāyapaṭipanno", "paliUp": "ÑĀYAPAṬIPANNO", "vi": "Thực hành đúng pháp để chứng ngộ chân lý", "group": "hanh", "short": "<p>Thực hành đúng phương pháp — tức Bát Chánh Đạo — nhằm mục đích duy nhất là chứng ngộ Níp-bàn.</p>", "detail": "<p><b>Ñāya</b> chỉ <b>Thánh Đạo tám ngành</b>, cũng chỉ chính Níp-bàn — mục tiêu cần chứng đạt. Chư Tăng thực hành nhắm thẳng vào mục đích ấy, không vì danh lợi, không vì được sanh về cõi trời.</p><p>Đây là ân đức nêu rõ <i>tính đúng phương pháp</i> của Tăng-già: hành theo con đường mà chư Phật đã chỉ, chứ không tự chế ra lối đi riêng.</p>"}, {"n": 4, "pali": "Sāmīcipaṭipanno", "paliUp": "SĀMĪCIPAṬIPANNO", "vi": "Thực hành xứng đáng được tôn kính", "group": "hanh", "short": "<p>Thực hành đúng mực, thích hợp và hòa hợp, khiến chư Tăng xứng đáng nhận sự cung kính, đảnh lễ của chư thiên và nhân loại.</p>", "detail": "<p><b>Sāmīci</b> = sự thích đáng, đúng mực, đáng được kính lễ. Chư Tăng thực hành đến mức khiến pháp hành của mình trở thành nơi xứng đáng cho mọi hành động cung kính: chắp tay, đảnh lễ, đứng dậy tiếp đón, nhường chỗ ngồi.</p><p>Bốn ân đức đầu (Supaṭipanno, Ujupaṭipanno, Ñāyapaṭipanno, Sāmīcipaṭipanno) nói về <b>pháp hành</b> của Tăng; năm ân đức sau nói về <b>giá trị</b> của Tăng đối với thế gian.</p>"}, {"n": 5, "pali": "Āhuneyyo", "paliUp": "ĀHUNEYYO", "vi": "Xứng đáng thọ nhận lễ vật cúng dường", "group": "quy", "short": "<p>Xứng đáng nhận những vật cúng dường được mang đến từ xa, vì cúng dường đến Tăng cho quả lớn.</p>", "detail": "<p><b>Āhuna</b> là lễ phẩm được mang đến từ nơi xa để dâng cúng. Chư Tăng xứng đáng thọ nhận vì các ngài có giới thanh tịnh, làm cho vật cúng dường trở nên có quả lớn, lợi ích lớn cho thí chủ.</p><p>Chú giải ví: cùng một hạt giống, gieo vào ruộng xấu thì kém, gieo vào ruộng tốt thì bội thu.</p>"}, {"n": 6, "pali": "Pāhuneyyo", "paliUp": "PĀHUNEYYO", "vi": "Xứng đáng được đón tiếp như thượng khách", "group": "quy", "short": "<p>Xứng đáng nhận phần vật thực dành riêng cho khách quý, vì chư Tăng là vị khách quý nhất mà một gia đình có thể đón tiếp.</p>", "detail": "<p><b>Pāhuna</b> là phẩm vật dành cho khách quý, thân thuộc từ xa đến. Người đời dành phần ngon nhất để đãi khách; nhưng chư Thánh Tăng còn quý hơn mọi người khách, vì các ngài chỉ xuất hiện trong thời có Đức Phật và đem lại lợi lạc lâu dài.</p>"}, {"n": 7, "pali": "Dakkhiṇeyyo", "paliUp": "DAKKHIṆEYYO", "vi": "Xứng đáng thọ nhận vật thí hồi hướng đời sau", "group": "quy", "short": "<p>Xứng đáng nhận vật thí được dâng với niềm tin nơi nghiệp quả đời sau, vì Tăng làm cho vật thí ấy sanh quả lớn.</p>", "detail": "<p><b>Dakkhiṇā</b> là vật thí được dâng cúng với lòng tin vào nghiệp và quả của nghiệp trong đời vị lai. Chư Tăng xứng đáng thọ nhận vì các ngài <i>thanh lọc</i> vật thí ấy, khiến quả của nó trở nên rộng lớn.</p><p>Ân đức này khác Āhuneyyo ở chỗ nhấn mạnh <b>tâm của thí chủ</b> — dâng cúng vì tin ở đời sau — chứ không chỉ ở vật phẩm.</p>"}, {"n": 8, "pali": "Añjalikaraṇīyo", "paliUp": "AÑJALIKARAṆĪYO", "vi": "Xứng đáng được chắp tay đảnh lễ", "group": "quy", "short": "<p>Xứng đáng để chư thiên và nhân loại chắp tay cung kính đảnh lễ.</p>", "detail": "<p><b>Añjali</b> là cử chỉ chắp hai tay đưa lên trán để tỏ lòng tôn kính cao nhất. Chư Thánh Tăng xứng đáng nhận cử chỉ ấy vì các ngài là bậc đã đoạn trừ hoặc đang trên đường đoạn trừ phiền não.</p><p>Sự đảnh lễ này không hướng đến cá nhân mà hướng đến <b>giới, định, tuệ</b> mà vị ấy thành tựu.</p>"}, {"n": 9, "pali": "Anuttaraṁ puññakkhettaṁ lokassa", "paliUp": "ANUTTARAṀ PUÑÑAKKHETTAṀ LOKASSA", "vi": "Phước điền vô thượng của thế gian", "group": "quy", "short": "<p>Là thửa ruộng phước không gì sánh bằng của thế gian: gieo một chút thiện nơi Tăng cũng trổ quả vô lượng.</p>", "detail": "<p><b>Puññakkhetta</b> = ruộng phước; <b>anuttara</b> = vô thượng, không gì hơn. Cũng như hạt giống gieo vào ruộng phì nhiêu thì trổ nhiều bông trái, hành động thiện dù nhỏ mà hướng đến chư Thánh Tăng cũng cho quả lớn.</p><p>Đây là ân đức <b>tổng kết</b> của Tăng bảo: bốn ân đức đầu nói pháp hành, bốn ân đức kế nói sự xứng đáng, ân đức thứ chín nói giá trị của Tăng đối với toàn thế gian — không có ruộng phước nào cao hơn.</p>"}]}};
